```rust
use std::convert::TryInto;
use std::io::Error;

#[derive(Debug, PartialEq)]
struct Interactive {
    throttle: u8,
    roll: u8,
    pitch: u8,
    yaw: u8,
}

fn to_vec(interactive: &Interactive) -> Result<Vec<u8>, Error> {
    let mut output = Vec::with_capacity(4);
    output.push(interactive.throttle);
    output.push(interactive.roll);
    output.push(interactive.pitch);
    output.push(interactive.yaw);
    Ok(output)
}

fn from_bytes(bytes: &[u8]) -> Result<Interactive, Error> {
    if bytes.len() != 4 {
        return Err(Error::new(std::io::ErrorKind::InvalidData, "Invalid byte length"));
    }
    let throttle = bytes[0];
    let roll = bytes[1];
    let pitch = bytes[2];
    let yaw = bytes[3];
    Ok(Interactive {
        throttle,
        roll,
        pitch,
        yaw,
    })
}

fn main() {
    let interactive = Interactive {
        throttle: 0,
        roll: 1,
        pitch: 2,
        yaw: 3,
    };
    let output: Vec<u8> = to_vec(&interactive).unwrap();
    let back: Interactive = from_bytes(&output).unwrap();
    assert_eq!(
        back,
        Interactive {
            throttle: 0,
            roll: 1,
            pitch: 2,
            yaw: 3,
        }
    );
}
```

In the solution, the `to_vec` function creates a new vector and pushes the fields of the `Interactive` struct into it. The `from_bytes` function extracts the fields from the byte slice and constructs a new `Interactive` struct. The main function demonstrates the usage of these functions by serializing an `Interactive` struct, deserializing it, and asserting that the deserialized struct matches the original input.

