use std::time::{Duration, Instant};

#[derive(Debug, PartialEq)]
enum ProtocolState {
    Init,
    Established,
    Closed,
}

macro_rules! assert_closed {
    ($x:expr) => {
        match $x {
            ProtocolState::Closed => {}
            state => panic!("State was {:?}, expected Closed", state),
        }
    };
}

macro_rules! assert_req_sent {
    ($x:expr) => {
        match $x {
            ProtocolState::Established => {}
            state => panic!("State was {:?}, expected Established", state),
        }
    };
}

fn main() {
    let mut state = ProtocolState::Init;

    // Transition from Init to Established
    match state {
        ProtocolState::Init => {
            state = ProtocolState::Established;
            assert_req_sent!(state);
        }
        _ => panic!("Invalid state transition"),
    }

    // Transition from Established to Closed
    match state {
        ProtocolState::Established => {
            state = ProtocolState::Closed;
            assert_closed!(state);
        }
        _ => panic!("Invalid state transition"),
    }

    // Transition from Closed to Init
    match state {
        ProtocolState::Closed => {
            state = ProtocolState::Init;
        }
        _ => panic!("Invalid state transition"),
    }
}
```

In this solution, we define the `ProtocolState` enum with the states `Init`, `Established`, and `Closed`. We then implement the `assert_closed!` and `assert_req_sent!` macros to validate the state transitions. Finally, we demonstrate the state transitions and use the macros to validate the transitions.

