use std::alloc::{alloc, dealloc, Layout};
use std::ptr;

struct Malloc;

impl Malloc {
    fn new() -> Malloc {
        Malloc
    }

    fn allocate(&self, size: usize) -> *mut u8 {
        let layout = Layout::from_size_align(size, std::mem::align_of::<u8>()).unwrap();
        match unsafe { alloc(layout) } {
            ptr if !ptr.is_null() => ptr as *mut u8,
            _ => panic!("Memory allocation failed"),
        }
    }

    fn deallocate(&self, ptr: *mut u8, size: usize) {
        let layout = Layout::from_size_align(size, std::mem::align_of::<u8>()).unwrap();
        unsafe { dealloc(ptr as *mut _, layout) };
    }
}

fn contains_panics() {
    let allocator = Malloc::new();
    let ptr = allocator.allocate(1000);
    // Use the allocated memory
    allocator.deallocate(ptr, 1000);
}
