use std::collections::HashMap;
use std::time::{Duration, Instant};

pub struct RateLimiter {
    request_limit: u32,
    time_window: Duration,
    client_requests: HashMap<String, Vec<Instant>>,
}

impl RateLimiter {
    pub fn new(request_limit: u32, time_window: Duration) -> Self {
        RateLimiter {
            request_limit,
            time_window,
            client_requests: HashMap::new(),
        }
    }

    pub fn allow_request(&mut self, client_id: &str) -> bool {
        let now = Instant::now();
        let requests = self.client_requests.entry(client_id.to_string()).or_insert(Vec::new());
        requests.retain(|&t| now.duration_since(t) <= self.time_window);
        if requests.len() < self.request_limit as usize {
            requests.push(now);
            true
        } else {
            false
        }
    }
}

#[cfg(test)]
mod tests {
