    use std::thread;

    #[test]
    fn test_rate_limiter() {
        let mut limiter = RateLimiter::new(2, Duration::from_secs(1));
        assert_eq!(limiter.allow_request("client1"), true);
        assert_eq!(limiter.allow_request("client1"), true);
        assert_eq!(limiter.allow_request("client1"), false);

        thread::sleep(Duration::from_secs(1));
        assert_eq!(limiter.allow_request("client1"), true);
    }
}
