        Circle {
            center,
            radius,
            outline_color,
            fill_color,
        }
    }
}

impl Shape for Circle {
    fn accept(&self, shape_visitor: &mut dyn ShapeVisitor) -> Result<(), Box<dyn Error>> {
        shape_visitor.visit_circle(self)
    }
}

impl fmt::Display for Circle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "Circle center: ({}, {}) radius: {} outline color: {} fill color: {}",
            self.center.x, self.center.y, self.radius, self.outline_color, self.fill_color
        )
    }
}

