    fn visit_rectangle(&mut self, rectangle: &Rectangle) -> Result<(), Box<dyn Error>>;
    fn visit_circle(&mut self, circle: &Circle) -> Result<(), Box<dyn Error>>;
}

struct ShapeInfoVisitor;

impl ShapeVisitor for ShapeInfoVisitor {
    fn visit_rectangle(&mut self, rectangle: &Rectangle) -> Result<(), Box<dyn Error>> {
