pub fn element_reference(interp: &mut Artichoke, value: Value, bit: Value) -> Result<Value, Error> {
    match value {
        Value::Array(arr) => {
            if let Ok(index) = bit.clone().try_into::<Int>(interp) {
                if let Some(val) = arr.get(index) {
                    Ok(val.clone())
                } else {
                    Err(Error::new(interp, "Index out of bounds"))
                }
            } else {
                Err(Error::new(interp, "Invalid index type for array"))
            }
        }
        Value::Hash(hash) => {
            if let Some(val) = hash.get(interp, &bit)? {
                Ok(val)
            } else {
                Err(Error::new(interp, "Key not found in hash"))
            }
        }
        _ => Err(Error::new(interp, "Unsupported data structure type")),
    }
}
```

