    type Err = NoteError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "b" | "♭" => Ok(Accidental::Flat),
            "#" | "♯" => Ok(Accidental::Sharp),
            "x" => Ok(Accidental::DoubleSharp),
            "𝄪" => Ok(Accidental::DoubleFlat),
            "" => Ok(Accidental::Natural),
            _ => Err(NoteError::InvalidAccidental),
        }
    }
}

fn parse_musical_note(input: &str) -> Result<(String, String), NoteError> {
    if let Some(captures) = REGEX_PITCH.find(input) {
        let pitch = captures.as_str().chars().next().unwrap().to_string();
        let accidental = &input[captures.end()..];
        let accidental = Accidental::from_str(accidental)?;
        Ok((pitch, accidental.to_string()))
    } else {
        Err(NoteError::InvalidNote)
    }
}
