fn execute_instructions(instruction_pointer: u64, code_segment: &[i64]) -> (u64, u64) {
    let mut ip = instruction_pointer;
    let mut code = code_segment.to_vec();

    while let Some(&instruction) = code.get(ip as usize) {
        if instruction > 0 {
            ip += instruction as u64;
        } else if instruction < 0 {
            ip -= instruction.abs() as u64;
        } else {
            return (ip, code.len() as u64);
        }
    }

    (ip, code.len() as u64)
}
