    title: String,
    author: String,
    available: bool,
}

impl Book {
    fn new(title: &str, author: &str) -> Book {
        Book {
            title: title.to_string(),
            author: author.to_string(),
            available: true,
        }
    }
}

fn add_book(title: &str, author: &str, library: &mut Vec<Book>) {
    let new_book = Book::new(title, author);
    library.push(new_book);
}

fn remove_book(title: &str, library: &mut Vec<Book>) {
    library.retain(|book| book.title != title);
}

fn search_book(title: &str, library: &Vec<Book>) -> Option<&Book> {
    library.iter().find(|book| book.title == title)
}

fn check_out_book(title: &str, library: &mut Vec<Book>) -> Result<(), &str> {
    if let Some(book) = library.iter_mut().find(|book| book.title == title && book.available) {
        book.available = false;
        Ok(())
    } else {
        Err("Book not available for checkout")
    }
}

fn return_book(title: &str, library: &mut Vec<Book>) -> Result<(), &str> {
    if let Some(book) = library.iter_mut().find(|book| book.title == title && !book.available) {
        book.available = true;
        Ok(())
    } else {
        Err("Book not checked out")
    }
}

fn main() {
    let mut library: Vec<Book> = Vec::new();

    add_book("The Catcher in the Rye", "J.D. Salinger", &mut library);
    add_book("To Kill a Mockingbird", "Harper Lee", &mut library);
    add_book("1984", "George Orwell", &mut library);

    let book_to_search = "To Kill a Mockingbird";
    match search_book(book_to_search, &library) {
        Some(book) => println!("Book found: {} by {}", book.title, book.author),
        None => println!("Book not found"),
    }

    let book_to_checkout = "1984";
    match check_out_book(book_to_checkout, &mut library) {
        Ok(()) => println!("{} checked out successfully", book_to_checkout),
        Err(msg) => println!("{}", msg),
    }

    let book_to_return = "1984";
    match return_book(book_to_return, &mut library) {
        Ok(()) => println!("{} returned successfully", book_to_return),
        Err(msg) => println!("{}", msg),
    }
}
```

