```rust
use serde_json::{Value, json};

struct ContainsIgnoreCase {
    value: String,
}

impl ContainsIgnoreCase {
    fn build(value: String) -> Self {
        ContainsIgnoreCase { value }
    }

    fn evaluate(&self, input: &Value) -> bool {
        if let Value::Array(arr) = input {
            for item in arr {
                if let Some(str_val) = item.as_str() {
                    if str_val.to_lowercase() == self.value.to_lowercase() {
                        return true;
                    }
                }
            }
        }
        false
    }
}

