use std::collections::HashMap;

enum Changed<C> {
    Added(C),
    Removed,
}

struct Change<I, C> {
    id: I,
    change: Changed<C>,
}

struct KeyValStore<I, C> {
    store: HashMap<I, C>,
}

impl<I: Eq + std::hash::Hash, C> KeyValStore<I, C> {
    fn new() -> Self {
        KeyValStore {
            store: HashMap::new(),
        }
    }

    fn insert(&mut self, id: I, value: C) {
        self.store.insert(id, value);
    }

    fn remove(&mut self, id: &I) {
        self.store.remove(id);
    }

    fn get(&self, id: &I) -> Option<&C> {
        self.store.get(id)
    }

    fn update(&mut self, msg: Change<I, C>) {
        match msg.change {
            Changed::Added(change) => {
                eprintln!("Added {:?}: {:?}", msg.id, change);
                self.insert(msg.id, change);
            }
            Changed::Removed => {
                eprintln!("Remove {:?}", msg.id);
                self.remove(&msg.id);
            }
        }
    }
}

fn main() {
    let mut store: KeyValStore<i32, String> = KeyValStore::new();
    store.update(Change {
        id: 1,
        change: Changed::Added("Value1".to_string()),
    });
    store.update(Change {
        id: 2,
        change: Changed::Added("Value2".to_string()),
    });
    store.update(Change {
        id: 1,
        change: Changed::Removed,
    });

    println!("{:?}", store.get(&2)); // Output: Some("Value2")
    println!("{:?}", store.get(&1)); // Output: None
}
```

In this solution, we define the `Changed` enum to represent the two types of changes: `Added` and `Removed`. We also define the `Change` struct to hold the id and the change type. The `KeyValStore` struct uses a `HashMap` to store the key-value pairs. We implement the required methods for the `KeyValStore` struct, including `new`, `insert`, `remove`, `get`, and `update`. The `update` method matches on the change type and calls the appropriate method to modify the store. Finally, in the `main` function, we demonstrate the usage of the `KeyValStore` by adding, removing, and retrieving values.

