    fn update_link_style_config(&mut self, new_style: LinkStyle) -> Result<(), String> {
        self.link_style = new_style;
        let toml = toml::to_string(&self).map_err(|e| format!("Failed to serialize config: {}", e))?;
        let path = Path::new(CLOG_CONFIG_FILE);
        let mut file = fs::File::create(path).map_err(|e| format!("Failed to create file: {}", e))?;
        file.write_all(toml.as_bytes()).map_err(|e| format!("Failed to write to file: {}", e))?;
        Ok(())
    }
}

