use std::time::Duration;
use actix_web::rt;
use tokio::time::{interval, Duration as TokioDuration};

fn schedule_task<F>(task_fn: F, interval: Duration) -> tokio::task::JoinHandle<()>
where
    F: Fn() + Send + 'static,
{
    let interval = interval;
    let task_fn = tokio::task::spawn(async move {
        let mut task = interval_at(Instant::now(), interval.to_std().expect("can't spawn on a negative interval"));
        loop {
            task_fn();
            task.tick().await;
        }
    });
    task_fn
}
```

