use std::sync::{Arc, Mutex};
use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll, Waker, RawWaker, RawWakerVTable, RawWakerVTable};
use std::sync::mpsc::{sync_channel, SyncSender, Receiver};
use std::thread;

// Custom executor struct
pub struct CustomExecutor {
    task_sender: SyncSender<Arc<Task>>,
    task_receiver: Receiver<Arc<Task>>,
}

impl CustomExecutor {
    pub fn new() -> Self {
        let (task_sender, task_receiver) = sync_channel(100);
        CustomExecutor {
            task_sender,
            task_receiver,
        }
    }

    pub fn run(&self) {
        let receiver = self.task_receiver.clone();
        thread::spawn(move || {
            while let Ok(task) = receiver.recv() {
                task.run();
            }
        });
    }
}

// Task struct
struct Task {
    future: Mutex<Option<Pin<Box<dyn Future<Output = ()> + Send>>>>,
    waker: Mutex<Option<Waker>>,
}

impl Task {
    fn new(future: Pin<Box<dyn Future<Output = ()> + Send>>) -> Arc<Self> {
        Arc::new(Task {
            future: Mutex::new(Some(future)),
            waker: Mutex::new(None),
        })
    }

    fn run(self: Arc<Self>) {
        let waker = waker_from_task(self.clone());
        let mut context = Context::from_waker(&waker);
        if let Some(mut future) = self.future.lock().unwrap().take() {
            if let Poll::Pending = future.as_mut().poll(&mut context) {
                *self.waker.lock().unwrap() = Some(waker);
                self.task_sender.send(self).unwrap();
            }
        }
    }
}

fn waker_from_task(task: Arc<Task>) -> Waker {
    let raw_waker = RawWaker::new(Arc::into_raw(task) as *const (), &VTABLE);
    unsafe { Waker::from_raw(raw_waker) }
}

static VTABLE: RawWakerVTable = RawWakerVTable::new(
    |data| unsafe { Arc::from_raw(data as *const Task) },
    |data| {
        let _ = Arc::from_raw(data as *const Task);
    },
    |data| unsafe { Arc::from_raw(data as *const Task) },
    |data| {
        let _ = Arc::from_raw(data as *const Task);
    },
);

// Implementing Executor trait for CustomExecutor
impl Executor for CustomExecutor {
    fn spawn(&self, future: Pin<Box<dyn Future<Output = ()> + Send>>) {
        let task = Task::new(future);
        self.task_sender.send(task).unwrap();
    }

    fn block_on(&self, future: Pin<Box<dyn Future<Output = ()> + Send>>) {
        let task = Task::new(future);
        task.run();
    }

    fn spawn_local(&self, future: Pin<Box<dyn Future<Output = ()> + Send>>) {
        let task = Task::new(future);
        task.run();
    }
}

