enum Tensor<T: Debug> {
    Tensor1(Vec<T>),
    Tensor2(Vec<Vec<T>),
    Tensor3(Vec<Vec<Vec<T>>),
}

impl<T: Debug> Tensor<T> {
    fn new(data: Vec<T>) -> Tensor<T> {
        Tensor::Tensor1(data)
    }

    fn shape(&self) -> (usize, usize, usize) {
        match self {
            Tensor::Tensor1(data) => (data.len(), 1, 1),
            Tensor::Tensor2(data) => (data.len(), data[0].len(), 1),
            Tensor::Tensor3(data) => (data.len(), data[0].len(), data[0][0].len()),
        }
    }

    fn get(&self, indices: (usize, usize, usize)) -> Option<&T> {
        match self {
            Tensor::Tensor1(data) => data.get(indices.0),
            Tensor::Tensor2(data) => data.get(indices.0).and_then(|row| row.get(indices.1)),
            Tensor::Tensor3(data) => data.get(indices.0).and_then(|row| row.get(indices.1)).and_then(|col| col.get(indices.2)),
        }
    }
}

