```rust
use std::sync::atomic::{AtomicPtr, Ordering};
use std::ptr;

struct Node<T> {
    data: T,
    next: Option<Box<Node<T>>>,
}

pub struct ConcurrentStack<T> {
    head: AtomicPtr<Node<T>>,
}

impl<T> ConcurrentStack<T> {
    pub fn new() -> Self {
        ConcurrentStack {
            head: AtomicPtr::new(ptr::null_mut()),
        }
    }

    pub fn push(&self, data: T) {
        let new_node = Box::new(Node {
            data,
            next: None,
        });
        let new_node_ptr = Box::into_raw(new_node);
        loop {
            let head = self.head.load(Ordering::Relaxed);
            unsafe {
                (*new_node_ptr).next = Some(Box::from_raw(head));
            }
            if self
                .head
                .compare_exchange(head, new_node_ptr, Ordering::Relaxed, Ordering::Relaxed)
                .is_ok()
            {
                break;
            }
        }
    }

    pub fn pop(&self) -> Option<T> {
        loop {
            let head = self.head.load(Ordering::Relaxed);
            if head.is_null() {
                return None;
            }
            let next = unsafe { (*head).next.as_ref().map(|node| Box::into_raw(node)) };
            if self
                .head
                .compare_exchange(head, next.unwrap_or(ptr::null_mut()), Ordering::Relaxed, Ordering::Relaxed)
                .is_ok()
            {
                unsafe {
                    let node = Box::from_raw(head);
                    return Some(node.data);
                }
            }
        }
    }

    pub fn is_empty(&self) -> bool {
        self.head.load(Ordering::Relaxed).is_null()
    }
}
```

In the solution, the `push` method uses a loop to atomically update the `head` pointer by creating a new node and setting its `next` pointer to the current head. The `pop` method also uses a loop to atomically update the `head` pointer by setting it to the next node in the stack. The `is_empty` method simply checks if the `head` pointer is null to determine if the stack is empty.

