use rcrypto::{digest::Digest, sha2::Sha256, sha1::Sha1, ripemd160::Ripemd160};
use siphasher::sip::SipHasher24;
use std::hash::Hasher;

fn custom_hash(input: &str) -> u64 {
    let mut sha256 = Sha256::new();
    sha256.input_str(input);
    let mut sha1 = Sha1::new();
    sha1.input_str(input);
    let mut ripemd160 = Ripemd160::new();
    ripemd160.input_str(input);

    let mut combined_hasher = SipHasher24::new_with_keys(sha256.result_str().parse().unwrap(), sha1.result_str().parse().unwrap());
    combined_hasher.write_u32(ripemd160.result_str().parse().unwrap());

    combined_hasher.finish()
}
