        self.twi.baudrate.write(|w| w.baudrate().bits(baud_rate));
    }

    fn write_data(&self, slave_address: u8, data: &[u8]) {
        // Write data to a slave device over the TWI interface
        self.twi.address.write(|w| unsafe { w.address().bits(slave_address) });
        for &byte in data {
            self.twi.txdata.write(|w| unsafe { w.txdata().bits(byte) });
            while self.twi.events_txdready.read().bits() == 0 {}
            self.twi.events_txdready.write(|w| w);
        }
    }

    fn read_data(&self, slave_address: u8, buffer: &mut [u8]) {
        // Read data from a slave device over the TWI interface
        self.twi.address.write(|w| unsafe { w.address().bits(slave_address) });
        for byte in buffer {
            while self.twi.events_rxdready.read().bits() == 0 {}
            *byte = self.twi.rxdata.read().bits();
            self.twi.events_rxdready.write(|w| w);
        }
    }
}
