fn register_uppercase_directive<'r>(registry: &mut Registry<'r>) {
    use juniper::DefaultScalarValue;

    // Define the directive input type
    struct UpperCaseDirective;

    impl juniper::marker::IsInputType<juniper::DefaultScalarValue> for UpperCaseDirective {}

    impl juniper::marker::GraphQLType<juniper::DefaultScalarValue> for UpperCaseDirective {
        type Context = ();
        type TypeInfo = ();

        fn name(_info: &()) -> Option<&str> {
            Some("UpperCase")
        }

        fn meta<'r>(
            _info: &(),
            registry: &mut juniper::Registry<'r, juniper::DefaultScalarValue>,
        ) -> juniper::meta::MetaType<'r, juniper::DefaultScalarValue> {
            let directive = juniper::meta::DirectiveType::new("UpperCase")
                .on_field()
                .argument(
                    juniper::meta::Argument::new("value", juniper::meta::InputValueType::string())
                        .default_value(""),
                );

            registry.add_directive(directive);
            juniper::meta::MetaType::Directive(juniper::meta::DirectiveMeta {
                name: "UpperCase",
                description: None,
                locations: vec![juniper::meta::DirectiveLocation::Field],
                args: vec![],
            })
        }
    }

    // Implement the logic for the UpperCase directive
    fn upper_case_directive<'r>(
        _executor: &Executor<'r, 'r, (), juniper::DefaultScalarValue>,
        value: &Value<juniper::DefaultScalarValue>,
        _field: &Field<juniper::DefaultScalarValue>,
    ) -> ExecutionResult {
        if let Value::String(s) = value {
            Ok(Value::String(s.to_uppercase()))
        } else {
            Err("The UpperCase directive can only be used on string fields".into())
        }
    }

    registry.register_directive("UpperCase", UpperCaseDirective);
    registry.register_field_directive("UpperCase", upper_case_directive);
}
