        DataProcessor {
            map: BTreeMap::new(),
        }
    }

    fn insert(&mut self, key: f64, value: String) {
        self.map.insert(key, value);
    }

    fn remove(&mut self, key: f64) {
        self.map.remove(&key);
    }

    fn get_value(&self, key: f64) -> Option<&String> {
        self.map.get(&key)
    }

