            None
        } else {
            let min_key = *self.map.keys().next().unwrap();
            let max_key = *self.map.keys().last().unwrap();
            Some((min_key, max_key))
        }
    }

    fn print_sorted(&self) {
        for (key, value) in &self.map {
            println!("{}: {}", key, value);
        }
    }
}

