fn convert_to_2d(input: &[i32], rows: usize, cols: usize) -> Option<Vec<Vec<i32>>> {
    if rows == 0 || cols == 0 || input.is_empty() || input.len() != rows * cols {
        return None;
    }

    let mut result = Vec::with_capacity(rows);
    for chunk in input.chunks(cols) {
        result.push(chunk.to_vec());
    }
    Some(result)
}
