use std::collections::HashMap;

pub struct IntegerCollection {
    occurrences: HashMap<i32, usize>,
}

impl IntegerCollection {
    pub fn new() -> Self {
        IntegerCollection {
            occurrences: HashMap::new(),
        }
    }

    pub fn add(&mut self, value: i32) {
        *self.occurrences.entry(value).or_insert(0) += 1;
    }

    pub fn remove(&mut self, value: i32) {
        if let Some(count) = self.occurrences.get_mut(&value) {
            if *count > 1 {
                *count -= 1;
            } else {
                self.occurrences.remove(&value);
            }
        }
    }

    pub fn count(&self, value: i32) -> usize {
        *self.occurrences.get(&value).unwrap_or(&0)
    }

    pub fn get_most_common(&self) -> Option<i32> {
        self.occurrences
            .iter()
            .max_by_key(|&(_, count)| count)
            .map(|(&value, _)| value)
    }
}

fn main() {
    let mut collection = IntegerCollection::new();
    collection.add(5);
    collection.add(7);
    collection.add(5);
    collection.add(7);
    collection.add(7);
    collection.remove(5);
    println!("Count of 7: {}", collection.count(7)); // Output: 3
    println!("Most common: {:?}", collection.get_most_common()); // Output: Some(7)
}
