```rust
// tokenizer.rs
pub fn tokenize_hashtags(input: &str) -> Vec<String> {
    let mut hashtags = Vec::new();
    let words = input.split_whitespace();

    for word in words {
        if word.starts_with('#') {
            // Remove any punctuation from the hashtag
            let cleaned_hashtag = word.trim_matches(|c: char| !c.is_alphanumeric());
            if !cleaned_hashtag.is_empty() {
                hashtags.push(cleaned_hashtag.to_string());
            }
        }
    }

    hashtags
}
