async fn needs_reindex(database: &Database) -> Result<bool, Error> {
    // If there is no transaction id, there is no data, so the view is "up-to-date"
    if let Some(current_transaction_id) = database.last_transaction_id().await? {
        let needs_reindex = {
            // When views finish updating, they store the last transaction_id
            // they mapped. If that value is current, we don't need to reindex
            let last_mapped_transaction_id = database.last_mapped_transaction_id().await?;
            current_transaction_id != last_mapped_transaction_id
        };
        Ok(needs_reindex)
    } else {
        Ok(false) // No transaction ID, view is "up-to-date"
    }
}
```

