        let secret_number = rand::thread_rng().gen_range(1, 101);
        let mut attempts = 0;
        loop {
            println!("I'm thinking of a number between 1 and 100.");
            println!("Take a guess:");
            let mut guess = String::new();
            io::stdin().read_line(&mut guess)
                .expect("Failed to read line");
            let guess: u32 = match guess.trim().parse() {
                Ok(num) => num,
                Err(_) => {
                    println!("Please enter a valid number!");
                    continue;
                }
            };
            attempts += 1;
            match guess.cmp(&secret_number) {
                std::cmp::Ordering::Less => println!("Too low!"),
                std::cmp::Ordering::Greater => println!("Too high!"),
                std::cmp::Ordering::Equal => {
                    println!("Congratulations! You guessed the number in {} attempts.", attempts);
                    break;
                }
            }
        }
        println!("Do you want to play again? (yes/no):");
        play_again.clear();
        io::stdin().read_line(&mut play_again)
            .expect("Failed to read line");
        if play_again.trim().to_lowercase() != "yes" {
            println!("Goodbye!");
            break;
        }
    }
}
