        pub struct $error {
            $(pub $field: $field_type),*
        }

        impl $error {
            pub fn new($($field: $field_type),*) -> Self {
                $error {
                    $($field),*
                }
            }

            pub fn message(&self) -> String {
                format!($message, $($field = self.$field),*)
            }
        }
    };
}

CustomError!(DatabaseError { query: String } = "Database error: Query '{}' failed");
CustomError!(NotFoundError { resource: String } = "Resource not found: '{}'");
CustomError!(ValidationError { validation: String } = "Validation error: '{}'");
```

