use std::collections::VecDeque;

// Definition for a binary tree node.
#[derive(Debug, PartialEq, Eq)]
pub struct TreeNode {
    pub val: i32,
    pub left: Option<Box<TreeNode>>,
    pub right: Option<Box<TreeNode>>,
}

impl TreeNode {
    #[allow(dead_code)]
    #[inline]
    pub fn new(val: i32) -> Self {
        TreeNode { val, left: None, right: None }
    }
}

fn level_order_traversal(arr: Vec<Option<i32>>) -> Vec<i32> {
    let mut result = Vec::new();
    if arr.is_empty() {
        return result;
    }

    let root = TreeNode::from(arr);
    let mut queue = VecDeque::new();
    queue.push_back(root);

    while let Some(node) = queue.pop_front() {
        result.push(node.val);
        if let Some(left) = node.left {
            queue.push_back(left);
        }
        if let Some(right) = node.right {
            queue.push_back(right);
        }
    }

    result
}

impl TreeNode {
    fn from(arr: Vec<Option<i32>>) -> Option<Box<TreeNode>> {
        if arr.is_empty() {
            return None;
        }

        let mut nodes = arr.into_iter().map(|val| {
            if let Some(v) = val {
                Some(Box::new(TreeNode::new(v)))
            } else {
                None
            }
        }).collect::<Vec<_>>();

        let root = nodes.remove(0);
        let mut queue = VecDeque::new();
        queue.push_back(root.as_ref());

        while let Some(parent) = queue.pop_front() {
            if let Some(node) = nodes.pop() {
                parent.as_ref().map(|p| p.left = node);
                queue.push_back(node.as_ref());
            }
            if let Some(node) = nodes.pop() {
                parent.as_ref().map(|p| p.right = node);
                queue.push_back(node.as_ref());
            }
        }

        root
    }
}
```

