use rustls::{ClientConfig, Certificate, PrivateKey, RootCertStore, internal::pemfile};

fn configure_tls_client(cert: Vec<u8>, key: Vec<u8>) -> Result<ClientConfig, Box<dyn std::error::Error>> {
    let mut cfg = ClientConfig::new();

    // Load the certificate and private key
    let cert = Certificate(cert);
    let key = PrivateKey(key);

    // Load default trust roots
    let mut root_store = RootCertStore::empty();
    root_store.add_server_trust_anchors(&webpki_roots::TLS_SERVER_ROOTS);
    cfg.root_store = root_store;

    // Set the client certificate and private key
