fn resolve_imports(code_blocks: Vec<&str>) -> HashMap<String, Vec<String>> {
    let mut imports_map: HashMap<String, Vec<String>> = HashMap::new();

    for block in code_blocks {
        if block.starts_with("pub use ") {
