use std::collections::HashMap;

struct TerminalMultiplexer {
    terminals: HashMap<String, String>,
    active_terminal: String,
}

impl TerminalMultiplexer {
    fn new() -> TerminalMultiplexer {
        let mut terminals = HashMap::new();
        terminals.insert("default".to_string(), "".to_string());
        TerminalMultiplexer {
            terminals,
            active_terminal: "default".to_string(),
        }
    }

    fn create(&mut self, id: &str) {
        self.terminals.insert(id.to_string(), "".to_string());
    }

    fn switch(&mut self, id: &str) -> &str {
        if self.terminals.contains_key(id) {
            self.active_terminal = id.to_string();
            "Switched to terminal"
        } else {
            "Terminal not found"
        }
    }

    fn display(&self) -> &str {
        if let Some(content) = self.terminals.get(&self.active_terminal) {
            content
        } else {
            "No content to display"
        }
    }
}

fn main() {
    let mut multiplexer = TerminalMultiplexer::new();
    multiplexer.create("terminal1");
    multiplexer.switch("terminal1");
    println!("{}", multiplexer.display());
}
