use std::io;

// Function to find all prime numbers up to n using Sieve of Eratosthenes
fn sieve_of_eratosthenes(n: usize) -> Vec<bool> {
    let mut is_prime: Vec<bool> = vec![true; n + 1];
    is_prime[0] = false;
    is_prime[1] = false;

    for i in 2..=(n as f64).sqrt() as usize {
        if is_prime[i] {
            let mut j = i * i;
            while j <= n {
                is_prime[j] = false;
                j += i;
            }
        }
    }
    is_prime
}

fn main() {
    let mut input = String::new();
    println!("Enter the limit to find prime numbers:");
    io::stdin().read_line(&mut input).expect("Failed to read input");
    let n: usize = input.trim().parse().expect("Invalid input");

    let primes = sieve_of_eratosthenes(n);
    println!("Prime numbers up to {}: ", n);
    for (i, &is_prime) in primes.iter().enumerate() {
        if is_prime {
            print!("{} ", i);
        }
    }
}
```

This solution first defines the `sieve_of_eratosthenes` function to find all prime numbers up to `n` using the Sieve of Eratosthenes algorithm. It then reads the input from the user, calls the function, and prints the prime numbers up to the specified limit.

