fn extract_substrings(input_string: &str) -> Vec<String> {
    let mut substrings: Vec<String> = Vec::new();
    let mut in_brackets = false;
    let mut current_substring = String::new();

    for c in input_string.chars() {
        if c == '[' {
            in_brackets = true;
        } else if c == ']' {
            in_brackets = false;
            if current_substring.len() > 2 {
                current_substring.pop(); // Remove last character
                current_substring.remove(0); // Remove first character
                substrings.push(current_substring.clone());
            }
            current_substring.clear();
        } else if in_brackets {
            current_substring.push(c);
        }
    }

    substrings
}
