use pest::Parser;
use pest::iterators::Pair;
use pest::error::Error;
use pest::prec_climber::{PrecClimber, Operator, Assoc};

#[derive(Parser)]
#[grammar = "calculator.pest"]
struct Calculator;

pub fn extended_calculate(line: &str) -> Result<f64, Error<Rule>> {
    let climber = PrecClimber::new(vec![
        Operator::new(Rule::add, Assoc::Left) | Operator::new(Rule::subtract, Assoc::Left),
        Operator::new(Rule::multiply, Assoc::Left) | Operator::new(Rule::divide, Assoc::Left),
        Operator::new(Rule::power, Assoc::Right),
        Operator::new(Rule::modulus, Assoc::Left),
        Operator::new(Rule::sqrt, Assoc::Right),
    ]);

    let pairs = Calculator::parse(Rule::calculation, line)?;
    let pair = pairs.single()?;
    Ok(climb(pair, &climber))
}

fn climb(pair: Pair<Rule>, climber: &PrecClimber<Rule>) -> f64 {
    fn as_float(pair: Pair<Rule>) -> f64 {
        pair.as_str().parse().unwrap()
    }

    let infix = |lhs: f64, op: Pair<Rule>, rhs: f64| match op.as_rule() {
        Rule::add      => lhs + rhs,
        Rule::subtract => lhs - rhs,
        Rule::multiply => lhs * rhs,
        Rule::divide   => lhs / rhs,
        Rule::power    => lhs.powf(rhs),
        Rule::modulus  => lhs % rhs,
        Rule::sqrt     => lhs.sqrt(),
        _ => unreachable!(),
    };

    climber.climb(pair.into_inner(), as_float, infix)
}
```

This solution extends the existing calculator by adding support for the modulus and square root operations. The `extended_calculate` function uses the `PrecClimber` to handle the new operations and evaluates the mathematical expressions accordingly. The `climb` function is modified to include the new operations and their respective evaluation logic.

