impl LeagueTable {
    pub fn with_clubs(clubs: &Vec<i32>) -> LeagueTable {
        let points = vec![0; clubs.len()];
        LeagueTable { clubs: clubs.clone(), points }
    }

    pub fn add_match_result(&mut self, team1_id: i32, team2_id: i32, result: MatchResult) {
        let team1_index = self.clubs.iter().position(|&id| id == team1_id);
        let team2_index = self.clubs.iter().position(|&id| id == team2_id);

        if let (Some(index1), Some(index2)) = (team1_index, team2_index) {
            match result {
                MatchResult::Team1Win => {
                    self.points[index1] += 3;
                }
                MatchResult::Team2Win => {
                    self.points[index2] += 3;
                }
                MatchResult::Draw => {
                    self.points[index1] += 1;
                    self.points[index2] += 1;
                }
            }
        }
    }

    pub fn get_position(&self, team_id: i32) -> Option<usize> {
        let team_index = self.clubs.iter().position(|&id| id == team_id);
        if let Some(index) = team_index {
            let team_points = self.points[index];
            let position = self.points.iter().filter(|&p| *p > &team_points).count() + 1;
            Some(position)
        } else {
            None
        }
    }
}

pub enum MatchResult {
    Team1Win,
    Team2Win,
    Draw,
}
