use std::cmp::Ordering;

struct Task {
    id: u32,
    priority: u32,
}

pub struct PriorityQueue {
    tasks: Vec<Task>,
}

impl PriorityQueue {
    pub fn new() -> PriorityQueue {
        PriorityQueue { tasks: Vec::new() }
    }

    pub fn insert(&mut self, task_id: u32, priority: u32) {
        let task = Task {
            id: task_id,
            priority,
        };
        self.tasks.push(task);
        self.heapify_up(self.tasks.len() - 1);
    }

    pub fn pop(&mut self) -> Option<u32> {
        if self.tasks.is_empty() {
            return None;
        }
        if self.tasks.len() == 1 {
            return Some(self.tasks.remove(0).id);
        }
        let last_index = self.tasks.len() - 1;
        self.tasks.swap(0, last_index);
        let min_task_id = self.tasks.pop().unwrap().id;
        self.heapify_down(0);
        Some(min_task_id)
    }

    fn heapify_up(&mut self, mut index: usize) {
        while index > 0 {
            let parent_index = (index - 1) / 2;
            if self.tasks[index].priority < self.tasks[parent_index].priority {
                self.tasks.swap(index, parent_index);
                index = parent_index;
            } else {
                break;
            }
        }
    }

    fn heapify_down(&mut self, mut index: usize) {
        let size = self.tasks.len();
        while index < size {
            let left_child_index = 2 * index + 1;
            let right_child_index = 2 * index + 2;
            let mut smallest = index;

            if left_child_index < size && self.tasks[left_child_index].priority < self.tasks[smallest].priority {
                smallest = left_child_index;
            }
            if right_child_index < size && self.tasks[right_child_index].priority < self.tasks[smallest].priority {
                smallest = right_child_index;
            }

            if smallest != index {
                self.tasks.swap(index, smallest);
                index = smallest;
            } else {
                break;
            }
        }
    }
}

fn main() {
    let mut priority_queue = PriorityQueue::new();
    priority_queue.insert(1, 30);
    priority_queue.insert(2, 20);
    priority_queue.insert(3, 40);
    priority_queue.insert(4, 10);

    println!("{:?}", priority_queue.pop()); // Output: Some(4)
    println!("{:?}", priority_queue.pop()); // Output: Some(2)
    println!("{:?}", priority_queue.pop()); // Output: Some(1)
    println!("{:?}", priority_queue.pop()); // Output: Some(3)
    println!("{:?}", priority_queue.pop()); // Output: None
}
```

