            data: DeleteData::default(),
            logger,
            tracer,
        }
    }

    pub fn delete_record(&self, record_id: u64) -> Result<(), Error> {
        self.logger.log("Starting deletion operation for record_id: {}", record_id);

        let span = self.tracer.span("delete_record").start();

        match self.data.delete_record(record_id) {
            Ok(()) => {
                self.logger.log("Record with id {} successfully deleted", record_id);
                span.finish();
                Ok(())
            }
            Err(err) => {
                self.logger.error("Failed to delete record with id {}: {}", record_id, err);
                span.finish_with_tag("error", format!("{}", err));
                Err(Error::DeletionFailed)
            }
        }
    }
}
