fn infix_to_postfix(tokens: Vec<String>) -> Vec<String> {
    // Implement the Shunting Yard algorithm to convert the infix expression to postfix notation
    // Return a vector of tokens in postfix notation
}

fn evaluate_postfix(postfix: Vec<String>) -> i32 {
    let mut stack: Vec<i32> = Vec::new();

    for token in postfix {
        if token.is_numeric() {
            stack.push(token.parse().unwrap());
        } else {
            let operand2 = stack.pop().unwrap();
            let operand1 = stack.pop().unwrap();
            let result = match token.as_str() {
                "+" => operand1 + operand2,
                "-" => operand1 - operand2,
                "*" => operand1 * operand2,
                "/" => operand1 / operand2,
                _ => panic!("Invalid operator"),
            };
            stack.push(result);
        }
    }

    stack.pop().unwrap()
}
