    let orientation = Vec3d::new(rotation_matrix.at_2d::<f64>(0, 0)?, rotation_matrix.at_2d::<f64>(1, 0)?, rotation_matrix.at_2d::<f64>(2, 0)?);

    Ok(Pose { position, orientation })
}
