pub fn additional_properties(attr: TokenStream, item: TokenStream) -> TokenStream {
    // Parse the attribute input to determine the allowed status of additional properties
    let allow_additional_properties: bool = match attr.to_string().as_str() {
        "true" => true,
        "false" => false,
        _ => panic!("Invalid value for additional_properties attribute. Use 'true' or 'false'."),
    };

