    if modified_item.contains("struct") {
        let additional_properties_code = if allow_additional_properties {
            "#[allow(unknown_properties)]"
        } else {
            "#[deny(unknown_properties)]"
        };
        modified_item = modified_item.replace("struct", &format!("{} struct", additional_properties_code));
    } else {
        panic!("additional_properties attribute can only be applied to structs representing JSON schemas.");
    }

    // Return the modified item as a TokenStream
    modified_item.parse().unwrap()
}
