fn expressive_words(s: String, words: Vec<String>) -> i32 {
    fn is_expressive(s: &str, word: &str) -> bool {
        let (mut i, mut j) = (0, 0);
        let (n, m) = (s.len(), word.len());
        let s: Vec<char> = s.chars().collect();
        let word: Vec<char> = word.chars().collect();

        while i < n && j < m {
            if s[i] != word[j] {
                return false;
            }
            let mut len_s = 1;
            let mut len_w = 1;
            while i + 1 < n && s[i] == s[i + 1] {
                i += 1;
                len_s += 1;
            }
            while j + 1 < m && word[j] == word[j + 1] {
                j += 1;
                len_w += 1;
            }
            if len_s < len_w || (len_s < 3 && len_s != len_w) {
                return false;
            }
            i += 1;
            j += 1;
        }
        i == n && j == m
    }

    let mut count = 0;
    for word in words {
        if is_expressive(&s, &word) {
            count += 1;
        }
    }
    count
}
