impl WadDirectory {
    pub fn new(content: &[u8]) -> Self {
        let info = WadInfo::new(content);

        let mut directory = WadDirectory {
            files: Vec::with_capacity(info.num_lumps as usize),
        };

        let offset = info.into_table_ofs as usize;

        for i in 0..info.num_lumps {
            let entry_offset = offset + i * WadFileEntry::SIZE as usize;
            let name_end = content[entry_offset..].iter().position(|&x| x == 0).unwrap_or(WadFileEntry::NAME_SIZE);
            let name = String::from_utf8_lossy(&content[entry_offset..entry_offset + name_end]).into_owned();
            let size = LittleEndian::read_u32(&content[entry_offset + WadFileEntry::SIZE_OFFSET..]);
            let file_entry = WadFileEntry {
                name,
                offset: entry_offset,
                size: size as usize,
            };
            directory.files.push(file_entry);
        }

        directory
    }
}
