struct Editor {
    text: String,
    undo_stack: Vec<Operation>,
}

enum Operation {
    Insert(usize, String),
    Delete(usize, usize, String),
}

impl Editor {
    fn new() -> Editor {
        Editor {
            text: String::new(),
            undo_stack: Vec::new(),
        }
    }

    fn insert_text(&mut self, text: &str, position: usize) {
        self.text.insert_str(position, text);
        self.undo_stack.push(Operation::Delete(position, position + text.len(), text.to_string()));
    }

    fn delete_text(&mut self, start: usize, end: usize) {
        let deleted = self.text[start..end].to_string();
        self.text.drain(start..end);
        self.undo_stack.push(Operation::Insert(start, deleted));
    }

    fn display_text(&self) -> &str {
        &self.text
    }

    fn undo(&mut self) {
        if let Some(operation) = self.undo_stack.pop() {
            match operation {
                Operation::Insert(pos, ref text) => {
                    self.text.drain(pos..pos + text.len());
                }
                Operation::Delete(start, _, ref deleted) => {
                    self.text.insert_str(start, deleted);
                }
            }
        }
    }
}
```

