    let invalid_address = "0x5aaeb6053f3e94c9b9a09f33669435e7ef1beaed";

    println!("Valid address: {}", validate_ethereum_address(valid_address)); // Output: true
    println!("Invalid address: {}", validate_ethereum_address(invalid_address)); // Output: false
}
