use rocket::request::{FromRequest, Request};
use rocket::http::Status;
use rocket::Outcome;

pub struct UserLoginData {
    pub name: String,
    pub password: String,
}

impl<'a, 'r> FromRequest<'a, 'r> for UserLoginData {
    type Error = String;

    fn from_request(request: &'a Request<'r>) -> Outcome<Self, Self::Error> {
        match request.headers().get_one("Authorization") {
            Some(auth_header) => {
                let parts: Vec<&str> = auth_header.split_whitespace().collect();
                if parts.len() != 2 || parts[0] != "Basic" {
                    return Outcome::Failure((Status::Unauthorized, "Invalid authorization header".to_string()));
                }
                let decoded = base64::decode(parts[1]).map_err(|_| "Invalid base64 encoding".to_string())?;
                let decoded_str = String::from_utf8(decoded).map_err(|_| "Invalid UTF-8 encoding".to_string())?;
                let credentials: Vec<&str> = decoded_str.splitn(2, ':').collect();
                if credentials.len() != 2 {
                    return Outcome::Failure((Status::Unauthorized, "Invalid credentials format".to_string()));
                }
                let name = credentials[0].to_string();
                let password = credentials[1].to_string();
                Outcome::Success(UserLoginData { name, password })
            }
            None => Outcome::Failure((Status::Unauthorized, "Missing authorization header".to_string())),
        }
    }
}
```

In this solution, the `from_request` method extracts the username and password from the `Authorization` header of the incoming request. It then decodes and validates the credentials, returning a `UserLoginData` instance if successful, or an appropriate error if the data is invalid.

