use std::fs::OpenOptions;
use std::os::unix::io::{AsRawFd, RawFd};
use std::sync::{Arc, Mutex};

struct FileLock {
    file: std::fs::File,
    locked: bool,
}

impl FileLock {
    fn new(file_path: &str) -> Result<FileLock, String> {
        match OpenOptions::new().write(true).create(true).open(file_path) {
            Ok(file) => Ok(FileLock { file, locked: false }),
            Err(err) => Err(format!("Failed to open file: {}", err)),
        }
    }

    fn acquire_lock(&mut self) -> Result<(), String> {
        if self.locked {
            return Err("File already locked".to_string());
        }
        match self.file.try_lock_exclusive() {
            Ok(_) => {
                self.locked = true;
                Ok(())
            }
            Err(err) => Err(format!("Failed to acquire lock: {}", err)),
        }
    }

    fn release_lock(&mut self) -> Result<(), String> {
        if !self.locked {
            return Err("File not locked".to_string());
        }
        match self.file.unlock() {
            Ok(_) => {
                self.locked = false;
                Ok(())
            }
            Err(err) => Err(format!("Failed to release lock: {}", err)),
        }
    }
}

impl AsRawFd for FileLock {
    fn as_raw_fd(&self) -> RawFd {
        self.file.as_raw_fd()
    }
}

fn main() {
    let file_path = "example.txt";
    let mut file_lock = FileLock::new(file_path).unwrap();

    match file_lock.acquire_lock() {
        Ok(_) => println!("Lock acquired"),
        Err(err) => println!("Failed to acquire lock: {}", err),
    }

    match file_lock.release_lock() {
        Ok(_) => println!("Lock released"),
        Err(err) => println!("Failed to release lock: {}", err),
    }
}
```

