```rust
use std::cell::RefCell;
use std::rc::Rc;

#[derive(Debug, PartialEq, Eq)]
pub struct Node {
    pub val: i32,
    pub left: Option<Rc<RefCell<Node>>>,
    pub right: Option<Rc<RefCell<Node>>>,
}

impl Node {
    pub fn new(val: i32) -> Rc<RefCell<Node>> {
        Rc::new(RefCell::new(Node {
            val,
            left: None,
            right: None,
        }))
    }
}

fn max_depth(root: Option<Rc<RefCell<Node>>>) -> i32 {
    match root {
        Some(node) => {
            let left_depth = max_depth(node.borrow().left.clone());
            let right_depth = max_depth(node.borrow().right.clone());
            1 + std::cmp::max(left_depth, right_depth)
        }
        None => 0,
    }
}

fn main() {
    let root = Node::new(3);
    let left = Node::new(9);
    let right = Node::new(20);
    let right_left = Node::new(15);
    let right_right = Node::new(7);

    root.borrow_mut().left = Some(left.clone());
    root.borrow_mut().right = Some(right.clone());
    right.borrow_mut().left = Some(right_left.clone());
    right.borrow_mut().right = Some(right_right.clone());

    assert_eq!(max_depth(Some(root)), 3);
}
```

