// Function to get the transformed view matrix for the camera
fn get_view_matrix(cx: &GraphicsContext, viewport: &Viewport) -> Matrix4<f32> {
    // Wait for synchronization fences
    let mut fence = Fence;
    cx.graphics.wait_fences(&mut [fence], true);
    cx.graphics.reset_fences(&mut [fence]);

    // Get the camera from the viewport
    let camera = viewport.camera();

    // Calculate the view matrix using the camera's position and orientation
    let eye = camera.position();  // Get the camera's position
    let center = eye + camera.forward();  // Calculate the center point based on the camera's forward direction
    let up = camera.up();  // Get the camera's up direction

    // Create and return the view matrix
    Matrix4::look_at(eye, center, up)
}
