use std::collections::HashSet;

fn parse_input(input: &str) -> (Vec<(String, Vec<(u32, u32)>)>, Vec<u32>, Vec<Vec<u32>>) {
    let mut sections = input.trim().split("\n\n");
    let rules = sections.next().unwrap().lines().map(|line| {
        let mut parts = line.split(": ");
        let name = parts.next().unwrap().to_string();
        let ranges = parts.next().unwrap().split(" or ").map(|range| {
            let mut bounds = range.split('-');
            let start = bounds.next().unwrap().parse().unwrap();
            let end = bounds.next().unwrap().parse().unwrap();
            (start, end)
        }).collect();
        (name, ranges)
    }).collect();
    let your_ticket = sections.next().unwrap().lines().skip(1).next().unwrap()
        .split(',').map(|num| num.parse().unwrap()).collect();
    let nearby_tickets = sections.next().unwrap().lines().skip(1).map(|line| {
        line.split(',').map(|num| num.parse().unwrap()).collect()
    }).collect();
    (rules, your_ticket, nearby_tickets)
}

fn is_valid_for_any_field(value: u32, rules: &[(String, Vec<(u32, u32)>)]) -> bool {
    rules.iter().any(|(_, ranges)| ranges.iter().any(|(start, end)| value >= *start && value <= *end))
}

fn sum_invalid_values(rules: &[(String, Vec<(u32, u32)>)], nearby_tickets: &[Vec<u32>]) -> u32 {
    let mut invalid_sum = 0;
    for ticket in nearby_tickets {
        for &value in ticket {
            if !is_valid_for_any_field(value, rules) {
                invalid_sum += value;
            }
        }
    }
    invalid_sum
}

fn main() {
    let input = "class: 1-3 or 5-7
row: 6-11 or 33-44
seat: 13-40 or 45-50

your ticket:
7,1,14

nearby tickets:
7,3,47
40,4,50
55,2,20
38,6,12";
    let (rules, _, nearby_tickets) = parse_input(input);
    let result = sum_invalid_values(&rules, &nearby_tickets);
    println!("{}", result); // Output: 71
}
```

