            pattern: pattern.to_string(),
            kind,
        }
    }

    pub fn is_match(&self, text: &str) -> bool {
        text.contains(&self.pattern)
    }

    pub fn find(&self, text: &str) -> Option<(TokenKind, usize)> {
        if let Some(index) = text.find(&self.pattern) {
            Some((self.kind.clone(), index))
        } else {
            None
        }
    }
}

pub struct TokenMatcher {
    rules: Vec<Rule>,
}

impl TokenMatcher {
    pub fn new() -> TokenMatcher {
        TokenMatcher { rules: Vec::new() }
    }

    pub fn add_rule(&mut self, rule: Rule) {
        self.rules.push(rule);
    }

    pub fn is_match(&self, text: &str) -> bool {
        self.rules.iter().any(|r| r.is_match(text))
    }

    pub fn find(&self, text: &str) -> Option<(TokenKind, usize)> {
        self.rules
            .iter()
            .rev()
            .filter_map(|r| r.find(text))
            .max_by(|a, b| a.1.cmp(&b.1))
    }
}
