use rand::seq::SliceRandom;

fn deal_cards(num_players: usize, num_cards_per_player: usize) -> Vec<Vec<String>> {
    let mut deck = vec![
        "Ace of Spades", "2 of Hearts", "King of Diamonds", "10 of Clubs",
        "Queen of Spades", "7 of Diamonds", "Jack of Hearts", "5 of Clubs"
    ].iter().map(|&s| s.to_string()).collect();

    deck.shuffle(&mut rand::thread_rng());

    let mut hands: Vec<Vec<String>> = vec![Vec::new(); num_players];

    for _ in 0..num_cards_per_player {
        for player in 0..num_players {
            if let Some(card) = deck.pop() {
                hands[player].push(card);
            }
        }
    }

    hands
}

fn main() {
