// date.rs
use std::time::{SystemTime, UNIX_EPOCH};

pub struct Date {
    day: u32,
    month: u32,
    year: u32,
}

impl Date {
    pub fn new(day: u32, month: u32, year: u32) -> Date {
        Date { day, month, year }
    }

    pub fn today() -> Date {
        let now = SystemTime::now();
        let since_epoch = now.duration_since(UNIX_EPOCH).expect("Time went backwards");
        let days_since_epoch = since_epoch.as_secs() / (60 * 60 * 24);
        let (year, month, day) = days_to_ymd(days_since_epoch as u32);
        Date { day, month, year }
    }

    pub fn is_before(&self, other: &Date) -> bool {
        if self.year < other.year {
            true
        } else if self.year == other.year {
            if self.month < other.month {
                true
            } else if self.month == other.month {
                self.day < other.day
            } else {
                false
            }
        } else {
            false
        }
    }

    pub fn add_days(&self, n: i32) -> Date {
        let days_since_epoch = ymd_to_days(self.year, self.month, self.day) + n as u32;
        let (year, month, day) = days_to_ymd(days_since_epoch);
        Date { day, month, year }
    }

    pub fn subtract_days(&self, n: i32) -> Date {
        let days_since_epoch = ymd_to_days(self.year, self.month, self.day) - n as u32;
        let (year, month, day) = days_to_ymd(days_since_epoch);
        Date { day, month, year }
    }
}

fn days_to_ymd(days: u32) -> (u32, u32, u32) {
    let year = days / 365 + 1970;
    let mut remaining_days = days % 365;
    let mut month = 1;
    let mut day = 1;
    let days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    for i in 0..12 {
        let days_in_current_month = if i == 1 && is_leap_year(year) { 29 } else { days_in_month[i] };
        if remaining_days < days_in_current_month {
            month = i as u32 + 1;
            day = remaining_days + 1;
            break;
        }
        remaining_days -= days_in_current_month;
    }
    (year, month, day)
}

fn ymd_to_days(year: u32, month: u32, day: u32) -> u32 {
    let mut days = (year - 1970) * 365;
    for y in 1970..year {
        if is_leap_year(y) {
            days += 1;
        }
    }
    let days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    for m in 1..month {
        days += days_in_month[(m - 1) as usize];
        if m == 2 && is_leap_year(year) {
            days += 1;
        }
    }
    days + day - 1
}

fn is_leap_year(year: u32) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}
