// Define the Heap struct
pub struct Heap<T> {
    data: Vec<T>,
}

impl<T: Ord> Heap<T> {
    // Create a new empty heap
    pub fn new() -> Self {
        Heap { data: Vec::new() }
    }

    // Insert a new value into the heap
    pub fn insert(&mut self, value: T) {
        self.data.push(value);
        self.heapify_up(self.data.len() - 1);
    }

    // Remove and return the root element of the heap
    pub fn pop(&mut self) -> Option<T> {
        if self.data.is_empty() {
            None
        } else {
            self.data.swap(0, self.data.len() - 1);
            let root = self.data.pop();
            self.heapify_down(0);
            root
        }
    }

    // Return a reference to the root element of the heap without removing it
    pub fn peek(&self) -> Option<&T> {
        self.data.get(0)
    }

    // Helper method to maintain the heap property after insertion
    fn heapify_up(&mut self, mut index: usize) {
        while index > 0 {
            let parent = (index - 1) / 2;
            if self.data[index] <= self.data[parent] {
                break;
            }
            self.data.swap(index, parent);
            index = parent;
        }
    }

    // Helper method to maintain the heap property after removal
    fn heapify_down(&mut self, mut index: usize) {
        let len = self.data.len();
        while index < len {
            let left = 2 * index + 1;
            let right = 2 * index + 2;
            let mut largest = index;

            if left < len && self.data[left] > self.data[largest] {
                largest = left;
            }
            if right < len && self.data[right] > self.data[largest] {
                largest = right;
            }

            if largest == index {
                break;
            }

            self.data.swap(index, largest);
            index = largest;
        }
    }
}
```

This solution provides a complete implementation of a max-heap using the `Heap` struct in Rust. The `new`, `insert`, `pop`, and `peek` methods are implemented to support basic heap operations. The `heapify_up` and `heapify_down` helper methods are used to maintain the heap property after insertion and removal.

