fn main() {
    loop {
        println!("Enter your choice (rock, paper, or scissors), or 'exit' to quit:");

        let mut player_choice = String::new();
        io::stdin().read_line(&mut player_choice).expect("Failed to read line");
        let player_choice = player_choice.trim().to_lowercase();

        if player_choice == "exit" {
            println!("Goodbye!");
            break;
        } else if player_choice != "rock" && player_choice != "paper" && player_choice != "scissors" {
            println!("Invalid choice. Please enter 'rock', 'paper', 'scissors', or 'exit'.");
            continue;
        }

        let computer_choice = match rand::thread_rng().gen_range(0..3) {
            0 => "rock",
            1 => "paper",
            _ => "scissors",
        };

        println!("You picked {}!", player_choice);
        println!("Computer picked {}!", computer_choice);

        match (player_choice.as_str(), computer_choice) {
            ("rock", "scissors") | ("paper", "rock") | ("scissors", "paper") => {
                println!("You win!");
            }
            ("rock", "paper") | ("paper", "scissors") | ("scissors", "rock") => {
                println!("Computer wins!");
            }
            _ => {
                println!("It's a tie!");
            }
        }
    }
}
```

