pub struct MimeCollection {
    mime_types: Vec<String>,
}

impl MimeCollection {
    pub fn new() -> Self {
        MimeCollection {
            mime_types: Vec::new(),
        }
    }

    pub fn add_mime_type(&mut self, mime_type: &str) {
        self.mime_types.push(mime_type.to_string());
    }

    pub fn remove_mime_type(&mut self, mime_type: &str) {
        self.mime_types.retain(|m| m != mime_type);
    }

    pub fn get_mime_types(&self) -> Vec<String> {
        self.mime_types.clone()
    }

    pub fn find_mime_type(&self, prefix: &str) -> Vec<String> {
        self.mime_types
            .iter()
            .filter(|m| m.starts_with(prefix))
            .cloned()
            .collect()
    }
}

fn main() {
