use std::fs;
use std::io;
use std::io::BufRead;
use std::io::BufReader;

#[derive(Debug)]
pub struct Options {
    pub run_server: bool,
    pub server_type: ServerType,
    pub host: String,
    pub port: i32,
    pub debug: bool,
    pub log_file: String,
}

#[derive(Debug)]
pub enum ServerType {
    Development,
    Production,
}

impl Default for Options {
    fn default() -> Options {
        Options {
            run_server: false,
            server_type: ServerType::Development,
            host: "localhost".to_string(),
            port: 8080,
            debug: true,
            log_file: "app.log".to_string(),
        }
    }
}

fn parse_config_file(file_path: &str) -> Result<Options, String> {
    let file = match fs::File::open(file_path) {
        Ok(f) => f,
        Err(_) => return Err("File not found".to_string()),
    };

    let reader = BufReader::new(file);
    let mut options = Options::default();

    for line in reader.lines() {
        let line = line.unwrap();
        let parts: Vec<&str> = line.split('=').collect();
        if parts.len() != 2 {
            return Err("Invalid format".to_string());
        }

        match parts[0] {
            "run_server" => options.run_server = parts[1].parse().unwrap(),
            "server_type" => options.server_type = match parts[1] {
                "Development" => ServerType::Development,
                "Production" => ServerType::Production,
                _ => return Err("Invalid server type".to_string()),
            },
            "host" => options.host = parts[1].to_string(),
            "port" => options.port = parts[1].parse().unwrap(),
            "debug" => options.debug = parts[1].parse().unwrap(),
            "log_file" => options.log_file = parts[1].to_string(),
            _ => return Err("Unknown field".to_string()),
        }
    }

    Ok(options)
}
```

