use core::ops;

pub type BufferSet4<V> = BufferSet<[V; 4]>;

pub struct BufferSet<S: Storage>
{
    inner: ::kernel::sync::Spinlock<Inner>,
    data: ::core::cell::UnsafeCell<S>,
}
unsafe impl<S: Storage + Send> Send for BufferSet<S> {}

impl<S: Storage> BufferSet<S> {
    pub fn new(initial_value: S) -> Self {
        BufferSet {
            inner: ::kernel::sync::Spinlock::new(Inner), // Initialize the spinlock
            data: ::core::cell::UnsafeCell::new(initial_value),
        }
    }

    pub fn get(&self) -> &S {
        let _lock = self.inner.lock(); // Acquire the lock
        unsafe { &*self.data.get() } // Return a reference to the inner data
    }

    pub fn get_mut(&self) -> &mut S {
        let _lock = self.inner.lock(); // Acquire the lock
        unsafe { &mut *self.data.get() } // Return a mutable reference to the inner data
    }
}
