use std::io;
use syn;
use proc_macro2;
use thiserror::Error;

#[derive(Error, Debug)]
enum Error {
    #[error("Failed to parse source code")]
    ParseError(#[from] syn::Error),
    #[error("Failed to find bridge module")]
    BridgeError,
    #[error("Type checking failed")]
    TypeCheckError,
    #[error("Failed to generate output")]
    GenerationError,
}

fn generate(source: &str, opt: Opt, header: bool) -> Result<Vec<u8>, Error> {
    proc_macro2::fallback::force();

    let syntax = syn::parse_file(&source).map_err(Error::ParseError)?;
    let bridge = find::find_bridge_mod(syntax).map_err(|_| Error::BridgeError)?;
    let namespace = &bridge.namespace;
    let apis = syntax::parse_items(&mut Errors::new(), bridge.module).map_err(Error::ParseError)?;
    let types = Types::collect(&mut Errors::new(), apis).map_err(Error::TypeCheckError)?;
    check::typecheck(&mut Errors::new(), namespace, apis, types).map_err(Error::TypeCheckError)?;
    let out = write::gen(namespace, apis, types, opt, header).map_err(|_| Error::GenerationError)?;

    Ok(out.content())
}
```
