fn dfs(graph: &Vec<Vec<usize>>, start_node: usize) -> Vec<usize> {
    let mut visited = vec![false; graph.len()];
    let mut traversal_order = Vec::new();
    dfs_helper(graph, start_node, &mut visited, &mut traversal_order);
    traversal_order
}

fn dfs_helper(graph: &Vec<Vec<usize>>, node: usize, visited: &mut Vec<bool>, traversal_order: &mut Vec<usize>) {
    visited[node] = true;
    traversal_order.push(node);
    for &neighbor in &graph[node] {
        if !visited[neighbor] {
            dfs_helper(graph, neighbor, visited, traversal_order);
        }
    }
}
```

The `dfs` function initializes a vector `visited` to keep track of visited nodes and an empty vector `traversal_order` to store the order of visited nodes. It then calls the `dfs_helper` function to perform the DFS traversal. The `dfs_helper` function marks the current node as visited, adds it to the traversal order, and recursively visits its unvisited neighbors.

