fn calculate_adler32_checksum(data: &[u8]) -> u32 {
    const MOD_ADLER: u32 = 65521; // largest prime smaller than 65536
    let mut s1: u32 = 1;
    let mut s2: u32 = 0;

    for &byte in data {
        s1 = (s1 + u32::from(byte)) % MOD_ADLER;
        s2 = (s2 + s1) % MOD_ADLER;
    }

    (s2 << 16) | s1
}

fn main() {
    let data = b"Hello, world!";
    let checksum = calculate_adler32_checksum(data);
    println!("Adler-32 checksum: {:x}", checksum);
}
```

