use alloc::boxed::Box;
use core::iter::FromIterator;

pub struct CustomQueue<T> {
    head: Option<Box<Node<T>>>,
    tail: *mut Node<T>,
}

struct Node<T> {
    element: T,
    next: Option<Box<Node<T>>>,
}

impl<T> CustomQueue<T> {
    pub fn new() -> Self {
        CustomQueue { head: None, tail: std::ptr::null_mut() }
    }

    pub fn enqueue(&mut self, element: T) {
        let new_tail = Box::new(Node {
            element,
            next: None,
        });
        let raw_tail: *mut _ = &mut *new_tail;
        if !self.tail.is_null() {
            unsafe { (*self.tail).next = Some(new_tail) };
        } else {
            self.head = Some(new_tail);
        }
        self.tail = raw_tail;
    }

    pub fn dequeue(&mut self) -> Option<T> {
        self.head.take().map(|head| {
            let head = *head;
            self.head = head.next;
            if self.head.is_none() {
                self.tail = std::ptr::null_mut();
            }
            head.element
        })
    }

    pub fn peek(&self) -> Option<&T> {
        self.head.as_ref().map(|head| &head.element)
    }

    pub fn is_empty(&self) -> bool {
        self.head.is_none()
    }
}

impl<T> Drop for CustomQueue<T> {
    fn drop(&mut self) {
        while let Some(_) = self.dequeue() {}
    }
}

fn main() {
    let mut queue: CustomQueue<i32> = CustomQueue::new();
    queue.enqueue(10);
    queue.enqueue(20);
    println!("{:?}", queue.peek()); // Output: Some(10)
    println!("{:?}", queue.dequeue()); // Output: Some(10)
    println!("{:?}", queue.dequeue()); // Output: Some(20)
    println!("{:?}", queue.dequeue()); // Output: None
    println!("{:?}", queue.is_empty()); // Output: true
}
```

