pub fn simple_spanning_tree<V: AsRef<[f32]>>(scores: &[V]) -> Vec<usize> {
    let num_vertices = scores.len();
    let mut visited = vec![false; num_vertices];
    let mut min_weights = vec![f32::INFINITY; num_vertices];
    let mut parent = vec![0; num_vertices];
    let mut result = vec![0; num_vertices];

    min_weights[0] = 0.0;
    parent[0] = -1;

    for _ in 0..num_vertices {
        let mut min_weight = f32::INFINITY;
        let mut min_index = 0;

        for i in 0..num_vertices {
            if !visited[i] && min_weights[i] < min_weight {
                min_weight = min_weights[i];
                min_index = i;
            }
        }

        visited[min_index] = true;

        for j in 0..num_vertices {
            if !visited[j] && scores[min_index].as_ref()[j] < min_weights[j] {
                parent[j] = min_index as i32;
                min_weights[j] = scores[min_index].as_ref()[j];
            }
        }
    }

    for i in 1..num_vertices {
        result[i] = parent[i] as usize;
    }

    result
}
```

This solution uses Prim's algorithm to find the simple spanning tree of the given graph. It initializes arrays to keep track of visited vertices, minimum weights, and parent vertices. Then, it iterates through the vertices to find the minimum weight edges and constructs the simple spanning tree.

