```rust
use std::str::FromStr;
use std::fmt::Debug;
use ndarray::{Array2, Array, s};
use crate::parse_error::ParseError;

pub fn parse_as_2d_matrix_with_filled_border<T: Clone + FromStr + Debug>(
    input_data: &str,
    border_size: usize,
    border_value: T,
) -> Result<Array2<T>, ParseError> {
    let input_data = input_data.trim();

    let (width, height) = get_2d_matrix_width_height(input_data);

    let mut matrix: Array2<T> = Array::from_elem(
        (height + border_size * 2, width + border_size * 2),
        border_value,
    );

    let mut borderless = matrix.slice_mut(s![
        (border_size..height + border_size),
        (border_size..width + border_size)
    ]);

    let mut row_index = 0;
    for line in input_data.lines() {
        let mut col_index = 0;
        for val in line.split_whitespace() {
            if let Ok(parsed_val) = val.parse() {
                borderless[[row_index, col_index]] = parsed_val;
                col_index += 1;
            } else {
                return Err(ParseError::new("Failed to parse input data"));
            }
        }
        row_index += 1;
    }

    Ok(matrix)
}

fn get_2d_matrix_width_height(input_data: &str) -> (usize, usize) {
    let mut width = 0;
    let mut height = 0;
    for line in input_data.lines() {
        let line_width = line.split_whitespace().count();
        if line_width > width {
            width = line_width;
        }
        height += 1;
    }
    (width, height)
}
