use std::fs::File;
use std::io::Read;
use std::path::{Path, Component};

fn is_network_interface_up(name: &str) -> bool {
    let path = Path::new(&Component::RootDir)
        .join("sys")
        .join("class")
        .join("net")
        .join(name)
        .join("operstate");

    if let Ok(mut file) = File::open(path) {
