fn parse_expression(input: &str) -> Option<Expression> {
    let parts: Vec<&str> = input.split("||").map(|s| s.trim()).collect();

    if parts.len() == 1 {
        Some(Expression::Value(parts[0].to_string()))
    } else if parts.len() == 2 {
        let left = Expression::Value(parts[0].to_string());
        let right = Expression::Value(parts[1].to_string());
        Some(Expression::Or(Box::new(left), Box::new(right)))
    } else {
        None
    }
}

