use std::fs;

fn needs_copy(original_path: &str, target_path: &str) -> Result<bool, std::io::Error> {
    let target_metadata = fs::metadata(target_path);

    match target_metadata {
        Ok(_) => {
            let original_metadata = fs::metadata(original_path)?;
            let original_modified_time = original_metadata.modified()?;
            let target_modified_time = fs::metadata(target_path)?.modified()?;
            Ok(original_modified_time > target_modified_time)
        }
        Err(_) => Ok(true), // Target file does not exist, needs copy
    }
}
```

