use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::sync::{Arc, Mutex};
use std::sync::mpsc;
use std::thread;

struct AsyncTaskScheduler {
    tasks: Arc<Mutex<Vec<Box<dyn Future<Output = ()> + Send>>>>,
}

impl AsyncTaskScheduler {
    fn new() -> Self {
        AsyncTaskScheduler {
            tasks: Arc::new(Mutex::new(Vec::new())),
        }
    }

    fn add_task<F>(&self, task: F)
    where
        F: Future<Output = ()> + Send + 'static,
    {
        self.tasks.lock().unwrap().push(Box::new(task));
    }

    fn run_tasks(&self) {
        let (sender, receiver) = mpsc::channel();

        for task in self.tasks.lock().unwrap().iter() {
            let sender = sender.clone();
            let task = task.clone();
            thread::spawn(move || {
                let mut rt = tokio::runtime::Runtime::new().unwrap();
                rt.block_on(task);
                sender.send(()).unwrap();
            });
        }

        drop(sender);

        for _ in 0..self.tasks.lock().unwrap().len() {
            receiver.recv().unwrap();
        }
    }
}

// Example usage
#[tokio::main]
async fn main() {
    let scheduler = AsyncTaskScheduler::new();

    scheduler.add_task(async {
        // Perform some asynchronous task
    });

    scheduler.add_task(async {
        // Perform another asynchronous task
    });

    scheduler.run_tasks();
}
```

In this solution, we define the `AsyncTaskScheduler` struct with methods to create a new instance, add tasks, and run the tasks. The `add_task` method adds a closure representing an asynchronous task to the scheduler's queue. The `run_tasks` method executes all the tasks in the scheduler's queue in the order they were added. The tasks are executed concurrently using threads and a multi-producer, single-consumer channel for synchronization.

