mod parse_wiktionary_en {
    pub struct Configuration {
        pub nodes: Vec<Node>,
    }

    pub enum Node {
        String(String),
        List(Vec<Node>),
    }

    pub fn create_configuration() -> Configuration {
        Configuration { nodes: Vec::new() }
    }

    pub fn parse(title: &str, nodes: &Vec<Node>) -> String {
        let mut result = String::new();
        result.push_str(&format!("Title: {}\n", title));
        for node in nodes {
            match node {
                Node::String(s) => result.push_str(&format!("{}\n", s)),
                Node::List(list) => {
                    let parsed_content = parse_nested_nodes(list, 1);
                    result.push_str(&parsed_content);
                }
            }
        }
        result
    }

    fn parse_nested_nodes(nodes: &Vec<Node>, level: usize) -> String {
        let mut result = String::new();
        for node in nodes {
            match node {
                Node::String(s) => result.push_str(&format!("{:indent$}{}\n", "", s, indent = level * 4)),
                Node::List(list) => {
                    let parsed_content = parse_nested_nodes(list, level + 1);
                    result.push_str(&parsed_content);
                }
            }
        }
        result
    }
}
```

