use serde::de::DeserializeOwned;
use serde_json::Value;

struct RpcCaller {
    name: String,
    current: usize,
    arguments: Vec<Value>,
}

impl RpcCaller {
    fn new(name: &str) -> RpcCaller {
        RpcCaller {
            name: name.to_string(),
            current: 0,
            arguments: Vec::new(),
        }
    }

    fn call<T: DeserializeOwned>(&mut self, arg: T) -> Option<T> {
        if self.current < self.arguments.len() {
            let val = serde_json::from_value(std::mem::take(&mut self.arguments[self.current])).unwrap();
            self.current += 1;
            Some(val)
        } else {
            panic!("not enough arguments for rpc call {:?}", self.name);
        }
    }

    pub fn arg_opt<T: DeserializeOwned>(&mut self) -> Option<T> {
        if self.current < self.arguments.len() {
            let val = serde_json::from_value(std::mem::take(&mut self.arguments[self.current])).unwrap();
            self.current += 1;
            Some(val)
        } else {
            None
        }
    }
}

fn main() {
    let mut rpc_caller = RpcCaller::new("example_rpc");

    // Simulate adding arguments to the RPC caller
    rpc_caller.arguments.push(serde_json::json!(10));
    rpc_caller.arguments.push(serde_json::json!("hello"));

