fn contains_non_ascii_byte_constants(source_code: &str) -> bool {
    let mut in_byte_constant = false;
    let mut in_escape_sequence = false;
    let mut non_ascii_found = false;

    for c in source_code.chars() {
        match c {
            'b' if !in_byte_constant => in_byte_constant = true,
            '\'' if in_byte_constant && !in_escape_sequence => in_byte_constant = false,
            '"' if in_byte_constant && !in_escape_sequence => in_byte_constant = false,
            '\\' if in_byte_constant => in_escape_sequence = !in_escape_sequence,
            _ if in_byte_constant && !in_escape_sequence && c.is_ascii() => (),
            _ if in_byte_constant && !in_escape_sequence => {
                non_ascii_found = true;
                break;
            }
            _ => (),
        }
    }

    non_ascii_found
}

fn main() {
    let code = r#"
        fn main() {
            let byte_constant = b"Hello, World!"; // ASCII characters only
            let non_ascii_constant = b"Привет, мир!"; // Contains non-ASCII characters
