fn calculate_gaussian_sum(size: usize, sigma: f64) -> f64 {
    let offset = size as isize / 2;
    let s = 2.0 * sigma * sigma;
    let mut sum = 0.0;

    for x in -offset..size as isize - offset {
        for y in -offset..size as isize - offset {
            let r = (x as f64 * x as f64 + y as f64 * y as f64).sqrt();
            let gaussian = (-r * r / s).exp();
            sum += gaussian;
        }
    }

    sum
}

