use std::collections::{HashMap, HashSet};

fn resolve_dependencies(components: &[&str], dependencies: &[(String, String)]) -> Vec<&str> {
    let mut graph: HashMap<&str, HashSet<&str>> = HashMap::new();
    let mut in_degree: HashMap<&str, usize> = HashMap::new();
    let mut result: Vec<&str> = Vec::new();

    for component in components {
        graph.insert(component, HashSet::new());
        in_degree.insert(component, 0);
    }

    for (dependent, dependency) in dependencies {
        graph.entry(dependency).or_insert(HashSet::new()).insert(dependent);
        *in_degree.entry(dependent).or_insert(0) += 1;
    }

    let mut queue: Vec<&str> = Vec::new();
    for (component, &degree) in &in_degree {
        if degree == 0 {
            queue.push(component);
        }
    }

    while let Some(component) = queue.pop() {
        result.push(component);
        if let Some(dependents) = graph.get(component) {
            for dependent in dependents {
                *in_degree.get_mut(dependent).unwrap() -= 1;
                if *in_degree.get(dependent).unwrap() == 0 {
                    queue.push(dependent);
                }
            }
        }
    }

    result
}

fn main() {
    let components = ["A", "B", "C", "D"];
    let dependencies = [("A".to_string(), "B".to_string()), ("B".to_string(), "C".to_string()), ("B".to_string(), "D".to_string())];
    let order = resolve_dependencies(&components, &dependencies);
    println!("{:?}", order); // Output: ["C", "D", "B", "A"]
}
```

