```rust
use crate::types::primitive::Float;
use serde::Deserialize;

/// Point on the map
#[derive(Clone, Debug, Deserialize)]
pub struct Location {
    /// Longitude as defined by sender
    pub longitude: Float,
    /// Latitude as defined by sender
    pub latitude: Float,
}

fn calculate_distance(location1: &Location, location2: &Location) -> f64 {
    const R: f64 = 6371.0; // Mean radius of the Earth in kilometers

    let lat1_rad = location1.latitude.to_radians();
    let lat2_rad = location2.latitude.to_radians();
    let delta_lat = (location2.latitude - location1.latitude).to_radians();
    let delta_long = (location2.longitude - location1.longitude).to_radians();

    let a = (delta_lat / 2.0).sin().powi(2) + lat1_rad.cos() * lat2_rad.cos() * (delta_long / 2.0).sin().powi(2);
    let c = 2.0 * a.sqrt().atan2((1.0 - a).sqrt());
    let distance = R * c;

    distance
}
```

This solution defines the `calculate_distance` function that takes two `Location` instances as input and calculates the distance between them using the Haversine formula. The function first converts the latitude and longitude to radians, then applies the Haversine formula to calculate the distance in kilometers. The result is returned as a `f64` value representing the distance between the two locations.

