use std::collections::HashMap;

fn word_frequency_counter(input: &str) -> HashMap<String, u32> {
    let mut frequency_map: HashMap<String, u32> = HashMap::new();

    for word in input.split_whitespace() {
        let normalized_word = word.trim_matches(|c: char| !c.is_alphanumeric()).to_lowercase();
        *frequency_map.entry(normalized_word.to_string()).or_insert(0) += 1;
    }

    frequency_map
}

