use std::collections::HashMap;
use std::io;
use std::io::Write;

struct Repository {
    name: String,
    stars: u32,
}

impl Repository {
    fn new(name: String, stars: u32) -> Self {
        Repository { name, stars }
    }
}

struct RepositoryManager {
    repositories: HashMap<String, Repository>,
}

impl RepositoryManager {
    fn new() -> Self {
        RepositoryManager {
            repositories: HashMap::new(),
        }
    }

    fn add_repository(&mut self, name: String, stars: u32) {
        let repository = Repository::new(name, stars);
        self.repositories.insert(repository.name.clone(), repository);
    }

    fn remove_repository(&mut self, name: &str) {
        self.repositories.remove(name);
    }

    fn update_stars(&mut self, name: &str, stars: u32) {
        if let Some(repository) = self.repositories.get_mut(name) {
            repository.stars = stars;
        }
    }

    fn find_highest_stars(&self) -> Option<&Repository> {
        self.repositories.values().max_by_key(|repo| repo.stars)
    }

    fn find_lowest_stars(&self) -> Option<&Repository> {
        self.repositories.values().min_by_key(|repo| repo.stars)
    }

    fn calculate_average_stars(&self) -> f64 {
        let total_stars: u32 = self.repositories.values().map(|repo| repo.stars).sum();
        let num_repositories = self.repositories.len() as u32;
        total_stars as f64 / num_repositories as f64
    }
}

fn main() {
    let mut manager = RepositoryManager::new();

    // Example usage
    manager.add_repository("repo1".to_string(), 100);
    manager.add_repository("repo2".to_string(), 200);
    manager.add_repository("repo3".to_string(), 50);

    println!("Average stars: {}", manager.calculate_average_stars());

    if let Some(repo) = manager.find_highest_stars() {
        println!("Repository with the highest stars: {} - {}", repo.name, repo.stars);
    }

    if let Some(repo) = manager.find_lowest_stars() {
        println!("Repository with the lowest stars: {} - {}", repo.name, repo.stars);
