fn sort_tvu_peers_by_staked_nodes(bank: &Bank, bank_epoch: u64, unsorted_peers: Vec<TVUPeer>) -> Vec<TVUPeer> {
    let staked_nodes = stakingUtils::staked_nodes_at_epoch(bank, bank_epoch);
    let mut peers_with_staked_nodes: Vec<(TVUPeer, u32)> = unsorted_peers
        .iter()
        .map(|peer| (peer.clone(), staked_nodes.get(&peer.name).cloned().unwrap_or(0)))
        .collect();

    peers_with_staked_nodes.sort_by(|(_, staked_nodes1), (_, staked_nodes2)| staked_nodes2.cmp(staked_nodes1));

    peers_with_staked_nodes.into_iter().map(|(peer, _)| peer).collect()
}
