        let trimmed_input = input.trim();
        if trimmed_input == "q" {
            return Err("User chose to quit".into());
        }

        if let Ok(index) = trimmed_input.parse::<usize>() {
            if index > 0 && index <= examples.len() {
                if let Some(example) = &examples[index - 1] {
                    return Ok(example.clone());
                }
            }
        }

        println!("Invalid input. Please choose a valid example or 'q' to quit:");
    }
