use std::collections::HashSet;

#[derive(Debug, PartialEq, Eq, Hash)]
struct Binding {
    name: String,
    value: i32,
}

struct OperationManager {
    operations: Vec<Operation>,
}

struct Operation {
    ops: Vec<String>,
    provided: HashSet<Binding>,
    cost: u32,
}

impl OperationManager {
    fn new() -> Self {
        OperationManager {
            operations: Vec::new(),
        }
    }

    fn add_operation(&mut self, ops: Vec<String>, provided: Vec<Binding>, cost: u32) {
        let provided_set: HashSet<Binding> = provided.into_iter().collect();
        let operation = Operation {
            ops,
            provided: provided_set,
            cost,
        };
        self.operations.push(operation);
    }

    fn bound(&self, op_index: usize, binding: Binding) -> bool {
        if let Some(operation) = self.operations.get(op_index) {
            operation.provided.contains(&binding)
        } else {
            false
        }
    }
}
