use std::collections::HashMap;
use std::cell::RefCell;

#[derive(Debug, PartialEq, Eq, Hash)]
enum FunctionId {
    Internal(String),
    // Other variants may exist
}

struct Function {
    id: FunctionId,
    // Other function properties
}

struct FunctionCache {
    cache: RefCell<HashMap<FunctionId, Box<dyn std::any::Any>>>,
}

impl FunctionCache {
    fn new() -> FunctionCache {
        FunctionCache {
            cache: RefCell::new(HashMap::new()),
        }
    }

    fn cache<F, T>(&self, f: F) -> Box<dyn Fn(FunctionId) -> T>
    where
        F: Fn(FunctionId) -> T,
        T: Clone,
    {
        let cache_ref = self.cache.clone();
        Box::new(move |id: FunctionId| {
            let mut cache = cache_ref.borrow_mut();
            if let Some(result) = cache.get(&id) {
                result.downcast_ref::<T>().unwrap().clone()
            } else {
                let result = f(id);
                cache.insert(id, Box::new(result.clone()) as Box<dyn std::any::Any>);
                result
            }
        })
    }

    fn clear_cache(&self) {
        self.cache.borrow_mut().clear();
    }
}

fn main() {
