    let result2 = cached_function(FunctionId::Internal("tag2".to_string()));
    let result3 = cached_function(FunctionId::Internal("tag1".to_string()));

    println!("{:?}", result1);
    println!("{:?}", result2);
    println!("{:?}", result3);

    function_cache.clear_cache();
}
