pub const FNV_PRIME: u64 = 1099511628211;

fn fnv1a_hash(input: &str) -> u64 {
    let mut hash: u64 = HASH_SEED;
    for byte in input.bytes() {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(FNV_PRIME);
    }
    hash
}

