use std::fs::File;
use std::io::{Write, Result};

pub struct Chunk {
    data: Vec<u8>,
    persisted: bool,
}

impl Chunk {
    pub fn new(size: usize) -> Chunk {
        Chunk {
            data: vec![0; size],
            persisted: false,
        }
    }

    pub fn allocate(size: usize) -> Chunk {
        Chunk::new(size)
    }

    pub fn deallocate(&mut self) {
        self.data.clear();
    }

    pub fn persist(&mut self, file_path: &str) -> Result<()> {
        let mut file = File::create(file_path)?;
        file.write_all(&self.data)?;
        self.persisted = true;
        Ok(())
    }
}

pub struct MemoryManager {
    chunks: Vec<Chunk>,
}

impl MemoryManager {
    pub fn new() -> MemoryManager {
        MemoryManager { chunks: Vec::new() }
    }

    pub fn allocate_chunk(&mut self, size: usize) -> &mut Chunk {
        let chunk = Chunk::allocate(size);
        self.chunks.push(chunk);
        self.chunks.last_mut().unwrap()
    }

    pub fn deallocate_chunk(&mut self, chunk: &mut Chunk) {
        chunk.deallocate();
        self.chunks.retain(|c| c as *const Chunk != chunk as *const Chunk);
    }

    pub fn persist_chunk(&mut self, chunk: &mut Chunk, file_path: &str) -> Result<()> {
        chunk.persist(file_path)
    }
}

fn main() {
    let mut memory_manager = MemoryManager::new();
    let mut chunk = memory_manager.allocate_chunk(1024);
    memory_manager.persist_chunk(&mut chunk, "chunk_data.bin").unwrap();
    memory_manager.deallocate_chunk(&mut chunk);
}
