fn check_palindrome(s: &Vec<u8>, len: usize) -> bool {
    let (first, second) = if len % 2 == 0 {
        s.split_at(len / 2)
    } else {
        let (a, b) = s.split_at(len / 2);
        (a, &b[1..])
    };

    first.iter().eq(second.iter().rev())
}
```

