pub struct Label<T> {
    text: Text,
    dest: Point2<f32>,
    phantom: PhantomData<T>,
}

impl<T> Label<T> {
    pub fn new(ctx: &mut Context, label_text: &str, bounds: Rect) -> Self {
        let dest = Point2::new(bounds.x, bounds.y);
        let mut text = Text::new(TextFragment::new(label_text));
        // ... (text rendering logic)
        Label {
            text,
            dest,
            phantom: PhantomData,
