struct AnalysisResult {
    round_size: usize,
    result: Result<RunResult, RunError>,
}

fn run_linearly_increasing_rounds<T>(
    target: &T,
    start_round_size: usize,
    round_size_step: usize,
    sample_size: usize,
) -> Vec<AnalysisResult>
where
    T: Target,
{
    let mut results = Vec::new();
    let mut round_size = start_round_size;

    for _ in 0..sample_size {
        let result = target.run(round_size);
        results.push(AnalysisResult {
            round_size,
            result,
        });
        round_size += round_size_step;
    }

    results
}
```

