use sha2::{Digest, Sha256};

struct PasswordEncoder;

impl PasswordEncoder {
    pub fn encode(raw_password: &str) -> String {
        let mut hasher = Sha256::new();
        hasher.update(raw_password);
        let digest = hasher.finalize();
        format!("{:x}", digest)
    }

