fn batches(
    self,
    vectorizer: Vectorizer,
    encoder: Encoder,
    max_len: usize,
) -> Vec<(EncodedSequence, EncodedLabel)> {
    let mut batches = Vec::new();

    for (sequence, label) in self.data.iter() {
        if sequence.len() <= max_len {
            let encoded_sequence = vectorizer.encode(sequence);
            let encoded_label = encoder.encode(label);
            batches.push((encoded_sequence, encoded_label));
        }
    }

    batches
