2. `find_next_set_hart(&self, start_hart_id: usize) -> Option<usize>`: This function should return an `Option<usize>` representing the hart id of the next set hart after the given `start_hart_id`. If no set hart is found after the given `start_hart_id`, the function should return `None`.

```rust
impl BitSet {
    pub fn is_set(&self, hart_id: usize) -> bool {
        assert!(hart_id <= self.max_hart_id);
        let (i, j) = split_index_usize(hart_id);
        (self.inner[i] & (1 << j)) != 0
    }

    pub fn find_next_set_hart(&self, start_hart_id: usize) -> Option<usize> {
        let mut i = start_hart_id / (std::mem::size_of::<usize>() * 8);
        let mut j = start_hart_id % (std::mem::size_of::<usize>() * 8);
        let mut inner_index = i;
        let mut bit_mask = 1 << j;

        while i < self.inner.len() {
            let remaining_bits = self.inner[i] & (!0 << j);
            if remaining_bits != 0 {
                let next_set_bit = remaining_bits.trailing_zeros() as usize;
                return Some(inner_index * (std::mem::size_of::<usize>() * 8) + next_set_bit);
            }
            i += 1;
            j = 0;
            inner_index += 1;
        }
        None
    }
}
