use std::time::{SystemTime, UNIX_EPOCH};

// Define the Block struct to represent a block in the blockchain
struct Block<T> {
    timestamp: u64,
    data: T,
    previous_hash: Vec<u8>,
    hash: Vec<u8>,
}

// Define the Hasher trait to specify the behavior of a hashing algorithm
trait Hasher {
    fn hash(&mut self, data: &[u8]) -> Vec<u8>;
}

// Implement the Block methods
impl<T> Block<T> {
    fn new(data: T, previous_hash: Vec<u8>, hasher: &mut dyn Hasher) -> Self {
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("Time went backwards")
            .as_secs();

        let mut block = Block {
            timestamp,
            data,
            previous_hash,
            hash: vec![0; 32], // Placeholder for the hash
        };

        let data_bytes = bincode::serialize(&block.data).unwrap();
        let mut input = vec![];
        input.extend_from_slice(&block.previous_hash);
        input.extend_from_slice(&data_bytes);

        block.hash = hasher.hash(&input);
        block
    }
}

// Define the Blockchain struct to manage the blocks
struct Blockchain<T> {
    blocks: Vec<Block<T>>,
    hasher: Box<dyn Hasher>,
}

// Implement the Blockchain methods
impl<T> Blockchain<T> {
    fn new(hasher: Box<dyn Hasher>) -> Self {
        Blockchain {
            blocks: Vec::new(),
            hasher,
        }
    }

    fn make_block(&mut self, data: T) {
        let previous_hash = match self.blocks.last() {
            Some(block) => block.hash.clone(),
            None => vec![0; 32], // Genesis block
        };

        let new_block = Block::new(data, previous_hash, &mut *self.hasher);
        self.blocks.push(new_block);
    }
}

// Example usage
fn main() {
    // Create a new SHA256 hasher
    let hasher = sha2::Sha256::new();
    let mut blockchain = Blockchain::new(Box::new(hasher));

    // Add blocks to the blockchain
    blockchain.make_block("Transaction 1");
    blockchain.make_block("Transaction 2");
}
```

In this solution, the `Block` struct represents a block in the blockchain, and the `Hasher` trait specifies the behavior of a hashing algorithm. The `Blockchain` struct manages the blocks and provides methods to create new blocks and maintain the integrity of the blockchain. The `make_block` method creates a new block with the given data and adds it to the blockchain, ensuring that the block's hash is calculated correctly and the blockchain is updated accordingly.

