fn encode(number: i32) -> Vec<u8> {
    let mut encoding = number.abs() << 1;
    if number < 0 {
        encoding += 1;
    }
    let mut bytes = Vec::new();
    while encoding > 0 {
        let mut byte = (encoding & 0x7f) as u8;
        encoding >>= 7;
        if encoding > 0 {
            byte |= 0x80;
        }
        bytes.push(byte);
    }
    bytes
}

fn decode(bytes: &[u8]) -> i32 {
    let mut result = 0;
    let mut shift = 0;
    for &byte in bytes {
        result |= ((byte & 0x7f) as i32) << shift;
        if byte & 0x80 == 0 {
            break;
        }
        shift += 7;
    }
    if result & 1 == 1 {
        -(result >> 1)
    } else {
        result >> 1
    }
}
```

