use super::*;
use mpsc_async::channel;
use std::sync::Arc;
use std::sync::Mutex;
use std::sync::mpsc::Sender;

struct ChatRoom {
    senders: Arc<Mutex<Vec<Sender<String>>>>
}

impl ChatRoom {
    fn new() -> ChatRoom {
        ChatRoom {
            senders: Arc::new(Mutex::new(Vec::new()))
        }
    }

    fn join(&self, sender: Sender<String>) {
        self.senders.lock().unwrap().push(sender);
    }

    fn send_message(&self, message: &str) {
        let senders = self.senders.lock().unwrap().clone();
        for sender in senders.iter() {
            sender.send(message.to_string()).unwrap();
        }
    }

    fn leave(&self, sender: Sender<String>) {
        let mut senders = self.senders.lock().unwrap();
        if let Some(pos) = senders.iter().position(|s| Arc::ptr_eq(&Arc::new(Mutex::new(s.clone())), &Arc::new(Mutex::new(sender.clone())))) {
            senders.remove(pos);
        }
    }
}
```

This solution creates a `ChatRoom` struct with methods for joining, sending messages, and leaving the chat room. It uses the `mpsc_async` module for asynchronous message passing between the users in the chat room. The `Arc` and `Mutex` are used to safely share the list of senders among multiple threads.

