struct CustomMap {
    map: std::collections::HashMap<i32, Vec<f64>>,
}

impl CustomMap {
    fn new() -> CustomMap {
        CustomMap {
            map: std::collections::HashMap::new(),
        }
    }

    fn insert(&mut self, key: i32, value: f64) {
        self.map.entry(key).or_insert(Vec::new()).push(value);
    }

    fn get(&self, key: i32) -> Option<&Vec<f64>> {
        self.map.get(&key)
    }

    fn remove(&mut self, key: i32) {
        self.map.remove(&key);
    }
}

impl PartialEq for CustomMap {
    fn eq(&self, other: &Self) -> bool {
        if self.map.len() != other.map.len() {
            return false;
        }
        for (key, values) in &self.map {
            if let Some(other_values) = other.map.get(key) {
                if values.len() != other_values.len() {
                    return false;
                }
                for value in values {
                    if !other_values.contains(value) {
                        return false;
                    }
                }
            } else {
                return false;
            }
        }
        true
    }
}

