use std::fs::File;
use std::io::{BufReader, BufRead};
use std::path::Path;

struct FileTokenizer {
    reader: BufReader<File>,
}

impl FileTokenizer {
    fn from_path(path: &Path) -> Result<FileTokenizer, String> {
        match File::open(path) {
            Ok(file) => Ok(FileTokenizer { reader: BufReader::new(file) }),
            Err(_) => Err("Cannot open file".to_string()),
        }
    }
}

impl Iterator for FileTokenizer {
    type Item = String;

    fn next(&mut self) -> Option<Self::Item> {
        let mut line = String::new();
        match self.reader.read_line(&mut line) {
            Ok(0) => None,
            Ok(_) => Some(line.trim().to_string()),
            Err(_) => None,
        }
    }
}

fn main() {
    let fname = std::env::args().nth(1).expect("Missing arg");
    let t = FileTokenizer::from_path(Path::new(&fname)).expect("Cannot Open");
    for token in t {
        println!("{:?}", token);
    }
}
