use std::mem;

fn hi_lo_sum(numbers: &[f64]) -> f64 {
    let mut partials: Vec<f64> = Vec::new();
    for &x in numbers {
        let mut i: usize = 0;
        while i < partials.len() {
            let y: f64 = partials[i];
            if x.abs() < y.abs() {
                mem::swap(&mut x, &mut partials[i]);
            }
            let hi = x + y;
            let lo = y - (hi - x);
            i += 1;
            if lo != 0.0 {
                partials.push(lo);
            }
            x = hi;
        }
        partials.push(x);
    }
    partials.iter().sum()
}

fn main() {
    let numbers = vec![0.1, 0.2, 0.3, 0.4];
    let sum = hi_lo_sum(&numbers);
    println!("Sum with high precision: {}", sum); // Output: Sum with high precision: 1.0
}
```

The `hi_lo_sum` function iterates through the input numbers and applies the `hi`/`lo` summation method to maintain exactness in the partial sums. It uses the provided code snippet as a reference to calculate the rounded sum in `hi` and the round-off in `lo`. Finally, the function returns the sum with high precision.

