use std::collections::{HashMap, HashSet};

fn process_mention_map(
    mention_map: &[(usize, HashSet<String>, usize, usize)],
    target_mention: &str,
    other_mention: &str,
) -> (HashMap<usize, usize>, HashMap<usize, isize>) {
    let mut virtual_register_counts: HashMap<usize, usize> = HashMap::new();
    let mut real_register_counts: HashMap<usize, isize> = HashMap::new();

    for (_, mention_set, vreg, rreg) in mention_map {
        if mention_set.contains(target_mention) {
            *virtual_register_counts.entry(*vreg).or_insert(0) += 1;
        }
        if mention_set.contains(other_mention) {
            *real_register_counts.entry(*rreg).or_insert(0) -= 1;
        }
    }

    (virtual_register_counts, real_register_counts)
}
```

