    // Send messages to the counter
    sender.send("increment").unwrap();
    sender.send("increment").unwrap();
    sender.send("decrement").unwrap();
    sender.send("increment").unwrap();
    sender.send("decrement").unwrap();
}

fn main() {
    run_counter();
}
