#[macro_export]
macro_rules! hash_map {
    ( $( $key:expr => $value:expr ),* ) => {
        {
            let mut temp_map = std::collections::HashMap::new();
            $(
                temp_map.insert($key, $value);
            )*
            temp_map
        }
    };
}

fn main() {
    let my_map = hash_map! {
        "key1" => 1,
        "key2" => 2,
        "key3" => 3,
    };
    println!("{:?}", my_map);
}
```
