    let mut input_string = String::new();
    std::io::stdin().read_line(&mut input_string)?;

    match shared_opts.cmd {
        Command::Escape => {
            let escaped_string = escape_string(&input_string);
            println!("{}", escaped_string);
        }
        Command::Unescape => {
            let unescaped_string = unescape_string(&input_string);
            println!("{}", unescaped_string);
        }
    }

    Ok(())
}

fn escape_string(input: &str) -> String {
    input.escape_default().to_string()
}

fn unescape_string(input: &str) -> String {
    input.replace("\\n", "\n").replace("\\t", "\t").replace("\\r", "\r")
}
