// basic_pitch.rs

pub fn note_to_number(note: &str, octave: i32) -> Option<i32> {
    let note_map = [
        ("C", 0), ("C#", 1), ("D", 2), ("D#", 3), ("E", 4), ("F", 5), ("F#", 6), ("G", 7), ("G#", 8), ("A", 9), ("A#", 10), ("B", 11)
    ];
    if let Some(&(_, base)) = note_map.iter().find(|&&(n, _)| n == note) {
        Some((octave + 1) * 12 + base)
    } else {
        None
    }
}

pub fn number_to_note(number: i32) -> Option<String> {
    if number >= 0 && number <= 127 {
        let note_map = [
            ("C", 0), ("C#", 1), ("D", 2), ("D#", 3), ("E", 4), ("F", 5), ("F#", 6), ("G", 7), ("G#", 8), ("A", 9), ("A#", 10), ("B", 11)
        ];
        let octave = (number / 12) - 1;
        let note = &note_map[(number % 12) as usize].0;
        Some(format!("{}{}", note, octave))
    } else {
        None
    }
}

pub fn transpose_pitch(pitch: i32, interval: i32) -> Option<i32> {
    let transposed_pitch = pitch + interval;
    if transposed_pitch >= 0 && transposed_pitch <= 127 {
        Some(transposed_pitch)
    } else {
        None
    }
}
