pub struct TextureManager {
    textures: HashMap<u32, Texture>,
    active_texture_unit: Option<Enum>,
}

impl TextureManager {
    pub fn new() -> Self {
        TextureManager {
            textures: HashMap::new(),
            active_texture_unit: None,
        }
    }

    pub fn add_texture(&mut self, texture: Texture) -> u32 {
        let id = self.textures.len() as u32;
        self.textures.insert(id, texture);
        id
    }

    pub fn activate_texture(&mut self, id: u32) {
        if let Some(texture) = self.textures.get(&id) {
            if let Some(unit) = self.active_texture_unit {
                unsafe {
                    gl::ActiveTexture(unit);
                    gl::BindTexture(gl::TEXTURE_2D, *texture);
                }
            }
        }
    }

    pub fn remove_texture(&mut self, id: u32) {
        self.textures.remove(&id);
    }
}

