```rust
use std::path::{Path, PathBuf};

#[derive(Debug)]
enum Component {
    Normal(String),
    Invalid(PathBuf),
}

#[derive(Debug)]
enum ErrorKind {
    InvalidPathComponent(PathBuf),
    Entry(Component),
}

#[derive(Debug)]
struct Error {
    kind: ErrorKind,
}

impl Error {
    fn from_kind(kind: ErrorKind) -> Error {
        Error { kind }
    }

    fn chain_err<F>(self, callback: F) -> Error
    where
        F: FnOnce() -> ErrorKind,
    {
        Error {
            kind: callback(),
        }
    }
}

fn validate_file_system(components: Vec<Component>) -> Result<(), Error> {
    for component in components {
        match component {
            Component::Normal(_) => {},
            invalid => {
                let bad_component: &Path = match invalid {
                    Component::Invalid(path) => path.as_ref(),
                    _ => unreachable!(),
                };
                return Err(Error::from_kind(ErrorKind::InvalidPathComponent(bad_component.to_path_buf())))
                    .chain_err(|| ErrorKind::Entry(invalid));
            },
        }
    }
    Ok(())
}

fn main() {
    let components = vec![
        Component::Normal("dir1".to_string()),
        Component::Invalid(PathBuf::from("invalid_dir")),
        Component::Normal("dir2".to_string()),
    ];

    match validate_file_system(components) {
        Ok(()) => println!("File system is valid"),
        Err(e) => println!("Error: {:?}", e),
    }
}
```

