use std::fs;

struct Node {
    children: Vec<Node>,
    metadata: Vec<u32>,
}

impl Node {
    fn new() -> Node {
        Node {
            children: Vec::new(),
            metadata: Vec::new(),
        }
    }
}

fn parse_input(filename: &str) -> Vec<u32> {
    let contents = fs::read_to_string(filename).expect("Failed to read file");
    contents
        .split_whitespace()
        .map(|s| s.parse().expect("Failed to parse number"))
        .collect()
}

fn build_tree(input: &mut Vec<u32>) -> Node {
    let num_children = input.remove(0) as usize;
    let num_metadata = input.remove(0) as usize;
    let mut node = Node::new();

    for _ in 0..num_children {
        node.children.push(build_tree(input));
    }

    for _ in 0..num_metadata {
        node.metadata.push(input.remove(0));
    }

    node
}

fn sum_metadata(node: &Node) -> u32 {
    let mut sum = node.metadata.iter().sum::<u32>();
    for child in &node.children {
        sum += sum_metadata(child);
    }
    sum
}

fn calculate_node_value(node: &Node) -> u32 {
    if node.children.is_empty() {
        return node.metadata.iter().sum();
    }

    let mut value = 0;
    for &index in &node.metadata {
        if let Some(child) = node.children.get(index as usize - 1) {
            value += calculate_node_value(child);
        }
    }
    value
}

fn main() {
    let input_file = "/home/assaf/dev/code/tmp/aocDay8.txt";
    let mut input = parse_input(input_file);
    let root = build_tree(&mut input);
    println!("Sum of metadata entries: {}", sum_metadata(&root));
    println!("Value of the root node: {}", calculate_node_value(&root));
}
